# it will be stopped from gui exit. 
class CheckSlopeTimerClass(QThread):
    def __init__(self, obj, interval, callback, parent=None):
        super(CheckSlopeTimerClass,self).__init__(parent)
        #print(threading.current_thread().name)
        self.count = 0
        self.ui = obj
        self.call = callback
        self.__event = threading.Event()
        self.__lock = threading.Lock()
        self.__interval = interval
        self.__isRun = False
        
    def run(self):
        self.__isRun = True
        try:
            while not self.__event.is_set():
                self.call()
                self.__event.wait(self.__interval)
        except Exception as e:
            print(self.getTracebackStr(traceback.format_exc()))

    def stop(self):
        if self.__isRun:
            self.__isRun = False
            self.__event.set()
            
    def Stop_thread(self):
        self.__isRun = False
        self.quit()

# it will be stopped from gui exit. 
class UserthreadLoopTask(QThread):
    signal = pyqtSignal(object)
    sig_msg = pyqtSignal(str, str, str)  # message to be shown to user

    def __init__(self, parent, callback):
        super(UserthreadLoopTask,self).__init__(parent)
        #print(threading.current_thread().name)
        self.pa = parent
        self.call = callback  
        self.running = False        
        self.paused = False
        self.pause_event = threading.Condition(threading.Lock())

    def run(self):
        while True:
            with self.pause_event:
                while self.paused:
                    self.pause_event.wait()
                    
                self.call(self.sig_msg)
                time.sleep(0.001)

    def pause(self):
        self.paused = True
        # If in sleep, we acquire immediately, otherwise we wait for thread
        # to release condition. In race, worker will still see self.paused
        # and begin waiting until it's set back to False
        self.pause_event.acquire()

    #should just resume the thread
    def resume(self):
        self.paused = False
        # Notify so thread will wake after lock released
        self.pause_event.notify()
        # Now release the lock
        self.pause_event.release()

# it will be stopped from gui exit.
class UserthreadSingleTask(QThread):
    signal = pyqtSignal(object)
    sig_msg = pyqtSignal(str, str, str)  # message to be shown to user
    
    def __init__(self, parent, callback):
        super(UserthreadSingleTask,self).__init__(parent)
        #print(threading.current_thread().name)
        self.pa = parent
        self.call = callback  
        self.running = False      
        self.paused = False
        self.pause_event = threading.Condition(threading.Lock())
        
    def run(self):
        self.running = True
        self.call(self.sig_msg)
        self.running = False
        time.sleep(0.001)

    def pause(self):
        self.paused = True
        # If in sleep, we acquire immediately, otherwise we wait for thread
        # to release condition. In race, worker will still see self.paused
        # and begin waiting until it's set back to False
        self.pause_event.acquire()

    #should just resume the thread
    def resume(self):
        self.paused = False
        # Notify so thread will wake after lock released
        self.pause_event.notify()
        # Now release the lock
        self.pause_event.release()

