        for index, value in enumerate(self.checkBox_tx_col_elements_status_b1['h']): 
            value.clicked.connect(partial(self._check_tx_cols_elements_status_b1, 'h', index))
        for index, value  in enumerate(self.checkBox_tx_col_elements_status_b1['v']): 
            value.clicked.connect(partial(self._check_tx_cols_elements_status_b1, 'v', index))
   

