        if not self.delete_ds_log: print(X_4_25)

        # Read data file and plot
        #df = pd.read_csv('EIRP_DATA.csv') #henter data fra Excel
        df = pd.read_csv("C:\\test_data\\EIRP_DATA_2.csv") #henter data fra Excel

        if not self.delete_ds_log: print('------------------------------------------')
        if not self.delete_ds_log: print(df)
