    def _sys_tick_time_measure(self, name, start):
        if not self.no_ticktime: 
            if start: 
                self.now1 = round(datetime.datetime.utcnow().timestamp() * 1000)
                if not self.delete_ds_log: print('[%s] %s' % (datetime.datetime.now(), name))
            else:
                self.now2 = round(datetime.datetime.utcnow().timestamp() * 1000)
                if not self.delete_ds_log: print('[%s] function tick time is (%s Sec)\n' % (datetime.datetime.now(), (self.now2 - self.now1)/1000)) 
                return str(round((self.now2 - self.now1)/1000,4))   
         
    def _sys_test_time_measure(self, name, start):        
        if not self.no_ticktime:  
            if start: 
                self.start = round(datetime.datetime.utcnow().timestamp() * 1000)
                if not self.delete_ds_log: print('[%s] %s' % (datetime.datetime.now(), name))
            else:
                self.end = round(datetime.datetime.utcnow().timestamp() * 1000)
                if not self.delete_ds_log: print('[ %s ] test tact time is (%s Sec)\n' % (datetime.datetime.now(), (self.end - self.start)/1000))   
                return str(round((self.end - self.start)/1000,4))

    def _sys_error_message(self, error):
        em = QtWidgets.QErrorMessage(self.main_widget)
        em.setWindowTitle("Error")
        em.showMessage(error.replace("\n", "<br>"))        

    def _sys_get_gui_state(self, state):
        if state in self.gui_states:
            return self.gui_states[state]
        else:
            if not self.delete_ds_log: print("{} is an unknown state!".format(state))
            return
           
    def _sys_set_log_level(self):
        pass

