    def run_azi_sweep(self, sig_msg):
        swp_speed = int(self.textboxes["3DP_sweep_speed"].text())        
        self.pos.query("CONF:FXT:SPD %d\r" % (swp_speed))
        
        start = int(self.textboxes["3DP_azi_start"].text())
        stop = int(self.textboxes["3DP_azi_stop"].text())
        step = int(self.textboxes["3DP_azi_step"].text())
        sleep = int(self.textboxes["3DP_azi_sleep"].text())
                    
        if (start-stop>0):
            sign=-1 
        else:
            sign=1
                    
        el_home = int(self.textboxes["3DP_el_home"].text()) 
                                
        for azi in np.arange(start, stop+sign, step*sign):              
            self.pos.move_to(el_home, azi)
            time.sleep(sleep/10e2)
                      
