    def run_sweep(self, sig_msg):
        #if not self.delete_ds_log: print("run_sweep")
                
        swp_speed = int(self.textboxes["3DP_sweep_speed"].text())        
        self.pos.query("CONF:FXT:SPD %d\r" % (swp_speed))
        
        azi_start = int(self.textboxes["3DP_azi_start"].text())
        azi_stop = int(self.textboxes["3DP_azi_stop"].text())
        azi_step = int(self.textboxes["3DP_azi_step"].text())
        azi_sleep = int(self.textboxes["3DP_azi_sleep"].text())
        
        el_start = int(self.textboxes["3DP_el_start"].text())
        el_stop = int(self.textboxes["3DP_el_stop"].text())
        el_step = int(self.textboxes["3DP_el_step"].text())
        el_sleep = int(self.textboxes["3DP_el_sleep"].text())
                
        if "Azimuth" in self.comboboxs['3DP_sweep_type'].currentText():      
            x_start = el_start
            x_stop = el_stop
            x_step = el_step
            x_sleep = el_sleep
            
            y_start = azi_start
            y_stop = azi_stop
            y_step = azi_step
            y_sleep = azi_sleep
            
        elif "Elevation" in self.comboboxs['3DP_sweep_type'].currentText():    
            x_start = azi_start
            x_stop = azi_stop
            x_step = azi_step
            x_sleep = azi_sleep
            
            y_start = el_start
            y_stop = el_stop
            y_step = el_step
            y_sleep = el_sleep
                                    
        if (x_start-x_stop>0):
            x_sign=-1 
        else:
            x_sign=1
                          
        if (y_start-y_stop>0):
            y_sign=-1 
        else:
            y_sign=1
                        
        for x in np.arange(x_start, x_stop+x_sign, x_step*x_sign):
            for y in np.arange(y_start, y_stop+y_sign, y_step*y_sign):  
                if "Azimuth" in self.comboboxs['3DP_sweep_type'].currentText():  
                    self.pos.move_to(x, y)
                elif "Elevation" in self.comboboxs['3DP_sweep_type'].currentText():  
                    self.pos.move_to(y, x)
                time.sleep(y_sleep/10e2)            
            time.sleep(x_sleep/10e2)
    
    def _inst_sweep(self):
        self._sys_thread_create(self.main_thread_group, 1, self.run_sweep)  
                  
