    def clear_results(self):  
        self.test_results.clear()
        for selband in ['low', 'mid', 'high']:
            self.test_results[selband] = self.test_names    
            for itmes,_ in self.test_names.items():    
                ''' test_results['selband']['evm_chp']['tx']['b1'] = {} '''
                self.test_results[selband][itmes] = {'tx' : {'b1': [], 'b2' : [], 'both' : []}, 'rx' : {'b1': [], 'b2' : [], 'both' : []}}
    
    def make_CarrierHeader(self, cc=1, template=''):
        res = []
        for i in range(len(template)):
            temp = ','.join('CC'+str(n)+'_'+template[i] for n in range(cc)).split(',')
            res = res + temp
        return res
     
    def make_NormalizationHeader(self, template=''):
        res = []
        Norm = ['Std','Min','Typ','Max','Del']
        
        for i in range(len(template)):
            temp = ','.join(template[i]+'_'+str(n) for n in Norm).split(',')
            res = res + temp
        return res
    
    def MeasureCableLoss(self, fstart=24.25e9, fend=29.5e9, fstep=10e6, Pin=0):
        print(" ===== TestScript.MeasureCableLoss =====\n")
        start = round(datetime.datetime.utcnow().timestamp() * 1000)
        res = []
        
        headerPrefix =  ['RF[GHz]','Pin[dBm]','Pout[dBm]','CableLoss[dB]','FSPL[dB]']
        header = headerPrefix
            
        swp_sheet = self.test_val.xL_create_work_sheet(self.wb_obj, "CableLoss")
        self.test_val.xL_write_row_bold(swp_sheet, 1, 1, header)
        self.wb_obj.save(self.results_fname)    
          
        try:               
            if self.ins[self._inst_get_current_if()[0]].is_connect(): 
                self.selected_if_index = self._inst_get_current_if()[0]
            else:
                if not self.delete_ds_log: print("%s is not connected!" % (self._inst_get_current_if()[1]))
                return
                
            if self.ins[self._inst_get_current_rf()[0]].is_connect():  
                self.selected_rf_index = self._inst_get_current_rf()[0]
            else:
                if not self.delete_ds_log: print("%s is not connected!" % (self._inst_get_current_rf()[1]))
                return
                
            # SG Settings  
            self.ins[self.selected_if_index].set_parameter(self.ins_mode.CONTINUOUS, self._inst_update_parameter(self.selected_if_index)) 
            self.ins[self.selected_if_index].set_sg(self.ins_port.IF, self.ins_mode.CONTINUOUS)
            self.ins[self.selected_if_index].set_output_power(self.ins_port.IF, str(Pin))
            self.ins[self.selected_if_index].set_modulation(self.ins_port.IF, "OFF")  
            self.ins[self.selected_if_index].set_rf(self.ins_port.IF, "OFF")  
            time.sleep(0.5)

            # SA Settings  
            self.ins[self.selected_rf_index].set_parameter(self.ins_mode.CONTINUOUS, self._inst_update_parameter(self.selected_rf_index)) 
            self.ins[self.selected_rf_index].set_sa(self.ins_port.RF, self.ins_mode.CONTINUOUS)  
            time.sleep(0.5)        
            
            freq_swp_range = np.arange(fstart, fend+fstep, fstep)/1.
            
            for idx, freq in enumerate(freq_swp_range):
                
                self.ins[self.selected_if_index].set_ul_freq(str(freq))
                self.ins[self.selected_if_index].set_dl_freq(str(freq))                
                self.ins[self.selected_if_index].set_rf(self.ins_port.IF, "ON")   
                self.ins[self.selected_rf_index].set_ul_freq(str(freq))            
                
                try:  
                    meas_res = float(self.ins[self.selected_rf_index].measure_start(self.ins_port.RF, int(self.textboxes["Measure_capture_cnt"].text()),0))
                    
                except Exception as e: 
                    print("Invalid measurement at Freq {:.2f} GHz".format(freq)); 
                                
                res = [freq,Pin,meas_res,meas_res-Pin,self.get_FSPL(freq)]  
                self.test_val.xL_append_row(swp_sheet, 1, res) 
            self.wb_obj.save(self.results_fname)
                            
            self.ins[self.selected_if_index].set_output_power(self.ins_port.IF, str(-25)) 
            self.ins[self.selected_if_index].set_rf(self.ins_port.IF, "OFF") 
            
        except Exception as e:
            if not self.no_save_log:   
                if self.f_meas: 
                    self.f_meas.close()
                    self.f_meas = 0
                
            print(self.getTracebackStr(traceback.format_exc()))  
        
        stop = round(datetime.datetime.utcnow().timestamp() * 1000)        
        tickTime = str(round((stop - start)/1000,4))
        print('\n[%s] TestScript.MeasureCableLoss: function tick time is (%s Sec)\n' % (datetime.datetime.now(), tickTime)) 
    
    def MeasureFrequencySweep_tx(self, meas=Test.spectrum, fstart=24.25e9, fend=29.5e9, fstep=10e6, Pin=-20, atten=0):      
              
        self.clear_results()  
        print(" ===== TestScript.MeasureFrequencySweep =====\n")
        start = round(datetime.datetime.utcnow().timestamp() * 1000)
        res = []
        offset_freq = 0
            
        band = self.FixedComboboxs["comboBox_tx_band"].currentText()
        txrx = self.FixedComboboxs['comboBox_txrx'].currentText()
        beam = self.FixedComboboxs['comboBox_beam'].currentText()
        pol = self.FixedComboboxs['comboBox_beam_pol'].currentText()
        
        headerPrefix =  ['Band','TRX','Beam','IF[Hz]', 'RF[Hz]', 'Pol', 'Pin[dBm]','Atten', 'Gain[dB]','Norm_gain[dB]','Avg_Temp[deg]', 'Power[dBm]']
        header = headerPrefix
       
        swp_sheet = self.test_val.xL_create_work_sheet(self.wb_obj, 'OutOfBandGain')
        self.test_val.xL_write_row_bold(swp_sheet, 1, 1, header)
        self.wb_obj.save(self.results_fname)    
            
        try:               
            if self.ins[self._inst_get_current_if()[0]].is_connect(): 
                self.selected_if_index = self._inst_get_current_if()[0]
            else:
                if not self.delete_ds_log: print("%s is not connected!" % (self._inst_get_current_if()[1]))
                return
                
            if self.ins[self._inst_get_current_rf()[0]].is_connect():  
                self.selected_rf_index = self._inst_get_current_rf()[0]
            else:
                if not self.delete_ds_log: print("%s is not connected!" % (self._inst_get_current_rf()[1]))
                return
                 
            # SG Settings  
            self.ins[self.selected_if_index].set_parameter(self.ins_mode.CONTINUOUS, self._inst_update_parameter(self.selected_if_index)) 
            self.ins[self.selected_if_index].set_sg(self.ins_port.IF, self.ins_mode.CONTINUOUS)
            self.ins[self.selected_if_index].set_output_power(self.ins_port.IF, str(Pin))
            self.ins[self.selected_if_index].set_modulation(self.ins_port.IF, "OFF")  
            self.ins[self.selected_if_index].set_rf(self.ins_port.IF, "OFF")              
            self.ins[self.selected_if_index].set_loss(self.ins_port.IF, 0)
            time.sleep(0.5)

            # SA Settings  
            self.ins[self.selected_rf_index].set_parameter(self.ins_mode.CONTINUOUS, self._inst_update_parameter(self.selected_rf_index)) 
            self.ins[self.selected_rf_index].set_sa(self.ins_port.RF, self.ins_mode.CONTINUOUS)             
            self.ins[self.selected_rf_index].set_loss(self.ins_port.RF, 0) 
            time.sleep(0.5)        
            
            self.gs.atten(txrx, atten)
            averageTempBefore = self.gs.read_avgtemp()[1]
            
            freq_swp_range = np.arange(fstart, fend+fstep, fstep)/1.
                        
            for idx, freq in enumerate(freq_swp_range):
                
                self.ins[self.selected_if_index].set_ul_freq(str(freq))
                self.ins[self.selected_if_index].set_dl_freq(str(freq))                
                self.ins[self.selected_if_index].set_rf(self.ins_port.IF, "ON")  
                 
                offset_freq = 28e9 - (5e9 - freq)
                self.ins[self.selected_rf_index].set_ul_freq(str(offset_freq))            
                                                          
                IFCalTable = self.lossTable.loc[self.lossTable['Freq[Hz]'] == freq]
                IFLoss = IFCalTable['BRDCableLoss[dB]'].values[0]
                self.ins[self.selected_if_index].set_loss(self.ins_port.IF, IFLoss) 
                
                RFCalTable = self.lossTable.loc[self.lossTable['Freq[Hz]'] == offset_freq]
                RFLoss = RFCalTable['OTA_Loss_Ant1[dB]'].values[0]
                self.ins[self.selected_rf_index].set_loss(self.ins_port.RF, RFLoss) 
            
                try:  
                    meas_res = float(self.ins[self.selected_rf_index].measure_start(self.ins_port.RF, int(self.textboxes["Measure_capture_cnt"].text()),0))
                except Exception as e: 
                    print("Invalid measurement at Freq {:.2f} Hz".format(freq)); 
                                              
                Pout = meas_res
                Gain = Pout - Pin
                Norm_gain = 0
                Avg_temp = 0  
                
                print(" IF Freq = {:.2f} Hz, RF Freq = {:.2f} Hz, Pin = {:.2f} dBm, Pout = {:.2f} dBm, Gain = {:.2f} dB, IF Loss = {:.2f} dB, RF Loss = {:.2f} dB" \
                        .format(freq, offset_freq, Pin, Pout, Gain, IFLoss, RFLoss))            
                
                header = [band, txrx, beam, freq, offset_freq, pol, Pin, atten, Gain, Norm_gain, Avg_temp]  
                res =  header + [meas_res]             
                self.test_results[band][meas][txrx][beam].append(res)  
            
            averageTempAfter = self.gs.read_avgtemp()[1]
            averageTemperature = (averageTempAfter + averageTempBefore) / 2
            print(" ")
            print(" Average Temperature Before Tests = {} C".format(averageTempBefore))
            print(" Average Temperature After Tests = {} C".format(averageTempAfter))
            print(" Average Temperature = {} C".format(averageTemperature))
            print(" Temperature Delta = {} C\n".format(averageTempAfter - averageTempBefore))
                    
            temp_range = np.linspace(averageTempBefore,averageTempAfter,len(freq_swp_range))
            
            for idx, data in enumerate(self.test_results[band][meas][txrx][beam]):
                # totalPwr-(jumction_temp - avg_temp)*(TempCoefficient)
                data[9] = data[8] - (self.gs.junction_temp-temp_range[idx])*(self.TxTempCoefficient if (txrx=='tx') else self.RxTempCoefficient)
                data[10] = temp_range[idx]
                
                print(" IF Freq = {:.2f} Hz, RF Freq = {:.2f} Hz, Pin = {:.2f} dBm, Pout = {:.2f} dBm, Gain = {:.2f} dB, gain(norm) = {:.2f} dB, AvgTemp = {:.2f} deg" \
                        .format(data[3],data[4],data[6],data[11],data[8],data[9],data[10]))            
                
                self.test_val.xL_append_row(swp_sheet, 1, data) 
            self.wb_obj.save(self.results_fname)
                                
            self.ins[self.selected_if_index].set_output_power(self.ins_port.IF, str(-25)) 
            self.ins[self.selected_if_index].set_rf(self.ins_port.IF, "OFF") 
                
        except Exception as e:
            if not self.no_save_log:   
                if self.f_meas: 
                    self.f_meas.close()
                    self.f_meas = 0
                
            print(self.getTracebackStr(traceback.format_exc()))  
        
        stop = round(datetime.datetime.utcnow().timestamp() * 1000)        
        tickTime = str(round((stop - start)/1000,4))
        print('\n[%s] TestScript.MeasureFrequencySweep: function tick time is (%s Sec)\n' % (datetime.datetime.now(), tickTime))     
    
