    def get_FSPL(self, freq = 28e9):
        ''' Free Space Path Loss Calculator '''
        fspl = (4*math.pi*self.FSPL_distance_in_metres*freq/(3e8))
        return round((-20*(math.log(fspl,10))),2)
                      
