        # RF Measurement Settings
        if self.ins[self._inst_get_current_rf()[0]].is_connect() or self.simulation:  
            self.selected_rf_index = self._inst_get_current_rf()[0]
            pass
        else:
            if not self.delete_ds_log: print("%s is not connected!" % (self._inst_get_current_rf()[1]))
            return

        self.ins[self.selected_rf_index].set_parameter(self.ins_mode.MODULATION, self._inst_update_parameter(self.selected_rf_index))  
        self.ins[self.selected_rf_index].set_sg(self.ins_port.RF, self.ins_mode.MODULATION)
        self.ins[self.selected_rf_index].set_rf(self.ins_port.RF, "ON")          

        self.buttons["_inst_pxie58xx_rf_cw_on"].setEnabled(False)    
        self.buttons["_inst_pxie58xx_rf_mod_on"].setEnabled(False)  

