        #print(self.mv2850_para)

    def gumstick_set_frequency(self):
        self.if_freq_val = float(self.FixedlineEdits["lineEdit_if_1"].text())             # 5000 MHz        
        #self.rf_val = float(self.FixedlineEdits["lineEdit_rf_2"].text())                 # 28.0e9 Hz                                                                                    
        self.rf_val = float(self.FixedlineEdits["lineEdit_rf_1"].text())                  # 27.5 MHz       
        self.bb_val = float(self.FixedlineEdits["lineEdit_bb_1"].text())                  # 50 MHz
        self.ref_clock_val = float(self.FixedlineEdits["lineEdit_ref_clock_1"].text())    # 122.88 MHz
        
        self.set_frequency_calculator()
        
        if self.mv2850_frequency['rf'][self.Hz] < self.low_freq:
            self.FixedComboboxs["comboBox_tx_band"].setCurrentIndex(0)
        elif self.mv2850_frequency['rf'][self.Hz] >= self.low_freq and self.mv2850_frequency['rf'][self.Hz] <= self.high_freq:
            self.FixedComboboxs["comboBox_tx_band"].setCurrentIndex(1)
        else:
            self.FixedComboboxs["comboBox_tx_band"].setCurrentIndex(2)
                
        self.gumstick_set_parameters()            
        self.gumstick_attenuation_settings()
        
        '''
        if self.FixedComboboxs["comboBox_gs_type"].currentText() == "26 GS":
            self.gum_temp = MVBX265()
        elif self.FixedComboboxs["comboBox_gs_type"].currentText() == "28 GS":
            self.gum_temp = MVBX285()
        elif self.FixedComboboxs["comboBox_gs_type"].currentText() == "39 GS":
            self.gum_temp = MVBX395()
        '''
                        
    def set_frequency_calculator(self, sig_msg = None):
        self.lo_mix_Hz_val = self.rf_val * pow(10,6) - self.if_freq_val * pow(10,6)
        self.pll_out_Hz_val = self.lo_mix_Hz_val / 3

        self.mv2850_frequency = {'pll_out' : [self.pll_out_Hz_val / pow(10,6), self.pll_out_Hz_val,],   # MHz , Hz
                                'lo_mix' : [self.lo_mix_Hz_val / pow(10,6), self.lo_mix_Hz_val],        # MHz , Hz
                                'rf' : [self.rf_val, self.rf_val * pow(10,6)],                          # MHz , Hz
                                'if' : [self.if_freq_val, self.if_freq_val * pow(10,6)],                # MHz , Hz
                                'bb' : [self.bb_val, self.bb_val * pow(10,6)],                          # MHz , Hz
                                'ref_clock' : [self.ref_clock_val, self.ref_clock_val * pow(10,6)]}     # MHz , Hz

        if sig_msg:
            sig_msg.emit("FixedlineEdits", "lineEdit_pll_out_1", str(self.mv2850_frequency['pll_out'][self.MHz]))
            sig_msg.emit("FixedlineEdits", "lineEdit_pll_out_2", str(self.mv2850_frequency['pll_out'][self.Hz]))
            sig_msg.emit("FixedlineEdits", "lineEdit_lo_mix_1", str(self.mv2850_frequency['lo_mix'][self.MHz]))
            sig_msg.emit("FixedlineEdits", "lineEdit_lo_mix_2", str(self.mv2850_frequency['lo_mix'][self.Hz]))
            sig_msg.emit("FixedlineEdits", "lineEdit_rf_1", str(self.mv2850_frequency['rf'][self.MHz]))
            sig_msg.emit("FixedlineEdits", "lineEdit_rf_2", str(self.mv2850_frequency['rf'][self.Hz]))
            sig_msg.emit("FixedlineEdits", "lineEdit_if_1", str(self.mv2850_frequency['if'][self.MHz]))
            sig_msg.emit("FixedlineEdits", "lineEdit_if_2", str(self.mv2850_frequency['if'][self.Hz]))
            sig_msg.emit("FixedlineEdits", "lineEdit_bb_1", str(self.mv2850_frequency['bb'][self.MHz]))
            sig_msg.emit("FixedlineEdits", "lineEdit_bb_2", str(self.mv2850_frequency['bb'][self.Hz]))
            sig_msg.emit("FixedlineEdits", "lineEdit_ref_clock_1", str(self.mv2850_frequency['ref_clock'][self.MHz]))
            sig_msg.emit("FixedlineEdits", "lineEdit_ref_clock_2", str(self.mv2850_frequency['ref_clock'][self.Hz]))
        else:
            self.FixedlineEdits["lineEdit_pll_out_1"].setText(str(self.mv2850_frequency['pll_out'][self.MHz]))
            self.FixedlineEdits["lineEdit_pll_out_2"].setText(str(self.mv2850_frequency['pll_out'][self.Hz]))
            self.FixedlineEdits["lineEdit_lo_mix_1"].setText(str(self.mv2850_frequency['lo_mix'][self.MHz]))
            self.FixedlineEdits["lineEdit_lo_mix_2"].setText(str(self.mv2850_frequency['lo_mix'][self.Hz]))
            self.FixedlineEdits["lineEdit_rf_1"].setText(str(self.mv2850_frequency['rf'][self.MHz]))
            self.FixedlineEdits["lineEdit_rf_2"].setText(str(self.mv2850_frequency['rf'][self.Hz]))
            self.FixedlineEdits["lineEdit_if_1"].setText(str(self.mv2850_frequency['if'][self.MHz]))
            self.FixedlineEdits["lineEdit_if_2"].setText(str(self.mv2850_frequency['if'][self.Hz]))
            self.FixedlineEdits["lineEdit_bb_1"].setText(str(self.mv2850_frequency['bb'][self.MHz]))
            self.FixedlineEdits["lineEdit_bb_2"].setText(str(self.mv2850_frequency['bb'][self.Hz]))
            self.FixedlineEdits["lineEdit_ref_clock_1"].setText(str(self.mv2850_frequency['ref_clock'][self.MHz]))
            self.FixedlineEdits["lineEdit_ref_clock_2"].setText(str(self.mv2850_frequency['ref_clock'][self.Hz]))
                       
