    def _gum__run_norm_target_temp_read(self, sig_msg, name):
        try:         
            if sig_msg:   
                sig_msg.emit("FixedlineEdits", "lineEdit_temp_junction", str(self.gs.junction_temp)) 
                sig_msg.emit("FixedlineEdits", "lineEdit_tx_gain", str(round(float(self.FixedlineEdits["lineEdit_tx_out"].text())-float(self.FixedlineEdits["lineEdit_tx_in"].text()),3)))
                sig_msg.emit("FixedlineEdits", "lineEdit_tx_norm_gain", str(round(float(self.FixedlineEdits["lineEdit_tx_gain"].text())-(self.gs.junction_temp-float(self.FixedlineEdits["lineEdit_temp_feavg"].text()))*0.3,2)))
                sig_msg.emit("FixedlineEdits", "lineEdit_rx_gain", str(round(float(self.FixedlineEdits["lineEdit_rx_out"].text())-float(self.FixedlineEdits["lineEdit_rx_in"].text()),3)))
                sig_msg.emit("FixedlineEdits", "lineEdit_rx_norm_gain", str(round(float(self.FixedlineEdits["lineEdit_rx_gain"].text())-(self.gs.junction_temp-float(self.FixedlineEdits["lineEdit_temp_feavg"].text()))*0.2,2)))
            else:
                self.FixedlineEdits["lineEdit_temp_junction"].setText(str(self.gs.junction_temp))  
                self.FixedlineEdits["lineEdit_tx_gain"].setText(str(round(float(self.FixedlineEdits["lineEdit_tx_out"].text())-float(self.FixedlineEdits["lineEdit_tx_in"].text()),3)))
                self.FixedlineEdits["lineEdit_tx_norm_gain"].setText(str(round(float(self.FixedlineEdits["lineEdit_tx_gain"].text())-(self.gs.junction_temp-float(self.FixedlineEdits["lineEdit_temp_feavg"].text()))*0.3,2)))                        
                self.FixedlineEdits["lineEdit_rx_gain"].setText(str(round(float(self.FixedlineEdits["lineEdit_rx_out"].text())-float(self.FixedlineEdits["lineEdit_rx_in"].text()),3)))
                self.FixedlineEdits["lineEdit_rx_norm_gain"].setText(str(round(float(self.FixedlineEdits["lineEdit_rx_gain"].text())-(self.gs.junction_temp-float(self.FixedlineEdits["lineEdit_temp_feavg"].text()))*0.2,2)))                    
        except Exception as e:           
            #print(self.getTracebackStr(traceback.format_exc()))
            return False

    def gumstick_seq_gumstick(self, sig_msg, name):
        try:
            self._sys_tick_time_measure("self.gumstick_seq_gumstick", True)
                        
            if name:
                if sig_msg:
                    sig_msg.emit("FixedlineEdits", name, "")
                else:
                    self.FixedlineEdits[name].setText("")
                          
            if self.gs.isOpen():
                self.gs.Close()

            if not self.gs.isOpen():
                if self.FixedComboboxs["comboBox_gs_type"].currentText() == "26 GS":
                    self.gs = MVBX265()
                elif self.FixedComboboxs["comboBox_gs_type"].currentText() == "28 GS":
                    self.gs = MVBX285()
                elif self.FixedComboboxs["comboBox_gs_type"].currentText() == "39 GS":
                    self.gs = MVBX395()
                
                self.gumstick_set_parameters()
                self.set_frequency_calculator(sig_msg)
                print("-----------------------------------------------------")
                print("[Test Information]")
                print("Donor or Relay\t\t\t:\t",self.FixedComboboxs['comboBox_panel'].currentText())
                print("T/Rx Mode\t\t\t:\t",self.FixedComboboxs['comboBox_txrx'].currentText())
                print("band\t\t\t\t:\t", self.FixedComboboxs["comboBox_tx_band"].currentText())
                print("Beam\t\t\t\t:\t",self.FixedComboboxs['comboBox_beam'].currentText())
                print("Pol\t\t\t\t:\t",self.FixedComboboxs['comboBox_beam_pol'].currentText().lower())
                '''
                if self.FixedComboboxs['comboBox_txrx'].currentText() == "tx":
                    print("Mixer Tx Gain\t\t\t:\t", self.FixedComboboxs['comboBox_mix_tx_gain'].currentText())
                    print("Fe Tx Gain\t\t\t:\t", self.FixedComboboxs['comboBox_fe_tx_gain'].currentText())
                else:
                    print("Mixer Rx Gain\t\t\t:\t", self.FixedComboboxs['comboBox_mix_rx_gain'].currentText())
                    print("Fe Rx Gain\t\t\t:\t", self.FixedComboboxs['comboBox_fe_rx_gain'].currentText())
                '''
                print("Center Frequency\t\t:\t",self.FixedlineEdits["lineEdit_rf_2"].text())
                print("Initial Beam Index\t\t:\t",self.FixedComboboxs["comboBox_beam_index"].currentText())
                print("Initial Beam Mode\t\t:\t",self.FixedComboboxs["comboBox_beam_mode"].currentText())
                print("Triband(1), Single band(0)\t:\t",self.FixedCheckboxs['checkBox_triband'].checkState() == self.CHECKED if 1 else 0)
                print("-----------------------------------------------------")
                   
                self.gs.Open(port=int(self.FixedComboboxs["comboBox_gs_port"].currentText()))     

                if sig_msg:
                    sig_msg.emit("FixedlineEdits", "lineEdit_version", str(self.gs.get_version()))
                else:
                    self.FixedlineEdits["lineEdit_version"].setText(str(self.gs.get_version()))
                
            ret = self._sys_tick_time_measure("self.gumstick_seq_gumstick", False)
                 
            if name:
                if sig_msg:
                    sig_msg.emit("FixedlineEdits", name, ret)
                else:
                    self.FixedlineEdits[name].setText(str(ret))
            return True
        except Exception as e:
            print(self.getTracebackStr(traceback.format_exc()))
            return False
    
