    def gumstick_seq_run_load_beam_book_from_flash(self, sig_msg, name):
        try: 
            self._sys_tick_time_measure("self.gumstick_seq_run_load_beam_book_from_flash", True)
            if name:
                if sig_msg:
                    sig_msg.emit("FixedlineEdits", name, "")
                else:
                    self.FixedlineEdits[name].setText("")    
  
            if (self.FixedCheckboxs['checkBox_triband'].checkState() == self.UNCHECKED):
                for page_no in list(range(int(self.FixedlineEdits["lineEdit_cal_start_page"].text()), int(self.FixedlineEdits["lineEdit_cal_start_page"].text()) + int(self.FixedlineEdits["lineEdit_cal_no_pages"].text()))):
                    self.gs.run_load_beam_book_from_flash(page_no, 85)

                for page_no in list(range(int(self.FixedlineEdits["lineEdit_bbk_start_page"].text()), int(self.FixedlineEdits["lineEdit_bbk_start_page"].text()) + int(self.FixedlineEdits["lineEdit_bbk_no_pages"].text()))):
                    self.gs.run_load_beam_book_from_flash(page_no, 85)
            else:
                self.gs.flash_load_cal_data(panel=self.FixedComboboxs['comboBox_panel'].currentText(), band=self.FixedComboboxs["comboBox_tx_band"].currentText(), loc = [0,1])

            ret = self._sys_tick_time_measure("self.gumstick_seq_run_load_beam_book_from_flash", False)
            if name:
                if sig_msg:
                    sig_msg.emit("FixedlineEdits", name, ret)
                else:
                    self.FixedlineEdits[name].setText(str(ret))  
            return True
        except Exception as e:           
            print(self.getTracebackStr(traceback.format_exc()))
            return False
         
