    def _gum__seq_get_gumstick_read_avgtemp(self, sig_msg, name):
        try:
            self._sys_tick_time_measure("self._gum__seq_get_gumstick_read_avgtemp", True)
            if name:
                if sig_msg: 
                    sig_msg.emit("FixedlineEdits", name, "")
                else:
                    self.FixedlineEdits[name].setText("") 
            val  = 0
            val = self.gs.read_avgtemp()  
            
            val1 = self.gs.gs.pll[0].model.get_temp_rtl(prnt=False)  
            
            now = datetime.datetime.now()                        
            temp = now.strftime('%Y-%m-%d %H:%M:%S') +','+','.join(str(s) for s in val[0])+','+str(val[1])+','+str(val1)    
                                          
            with open(".\log.txt", "a") as file:
                file.write(temp+'\n')
                        
            if(val):
                if sig_msg:
                    sig_msg.emit("FixedlineEdits", "lineEdit_temp_fe0", str(round(val[0][0],2)))
                    sig_msg.emit("FixedlineEdits", "lineEdit_temp_fe1", str(round(val[0][1],2)))
                    sig_msg.emit("FixedlineEdits", "lineEdit_temp_fe2", str(round(val[0][2],2)))
                    sig_msg.emit("FixedlineEdits", "lineEdit_temp_fe3", str(round(val[0][3],2)))
                    sig_msg.emit("FixedlineEdits", "lineEdit_temp_fe4", str(round(val[0][4],2)))
                    sig_msg.emit("FixedlineEdits", "lineEdit_temp_fe5", str(round(val[0][5],2)))
                    sig_msg.emit("FixedlineEdits", "lineEdit_temp_fe6", str(round(val[0][6],2)))
                    sig_msg.emit("FixedlineEdits", "lineEdit_temp_fe7", str(round(val[0][7],2)))
                    sig_msg.emit("FixedlineEdits", "lineEdit_temp_feavg", str(round(val[1],2)))
                else:
                    self.FixedlineEdits["lineEdit_temp_fe0"].setText(str(round(val[0][0],2)))
                    self.FixedlineEdits["lineEdit_temp_fe1"].setText(str(round(val[0][1],2)))
                    self.FixedlineEdits["lineEdit_temp_fe2"].setText(str(round(val[0][2],2)))
                    self.FixedlineEdits["lineEdit_temp_fe3"].setText(str(round(val[0][3],2)))
                    self.FixedlineEdits["lineEdit_temp_fe4"].setText(str(round(val[0][4],2)))
                    self.FixedlineEdits["lineEdit_temp_fe5"].setText(str(round(val[0][5],2)))
                    self.FixedlineEdits["lineEdit_temp_fe6"].setText(str(round(val[0][6],2)))
                    self.FixedlineEdits["lineEdit_temp_fe7"].setText(str(round(val[0][7],2)))
                    self.FixedlineEdits["lineEdit_temp_feavg"].setText(str(round(val[1],2)))   

            ret = self._sys_tick_time_measure("self._gum__seq_get_gumstick_read_avgtemp", False)
            if name:
                if sig_msg: 
                    sig_msg.emit("FixedlineEdits", name, ret)
                else:
                    self.FixedlineEdits[name].setText(str(ret))
                
            self._gum__run_norm_target_temp_read(sig_msg, None)
            return val
        except Exception as e:           
            print(self.getTracebackStr(traceback.format_exc()))
            return False   
       
    def _gum__loop_get_gumstick_read_avgtemp(self, sig_msg):        
        self._sys_ui_lock()
        if int(self.FixedlineEdits['lineEdit_function_tt_A20_cnt'].text()) > 1:             
            print("Temp. Loop Count\t= cnt", int(self.FixedlineEdits['lineEdit_function_tt_A20_cnt'].text())) 
            print("Temp. Loop Interval(s)\t=", int(self.FixedlineEdits['lineEdit_function_tt_A20_int'].text())/1000)          
            for x in range(0, int(self.FixedlineEdits['lineEdit_function_tt_A20_cnt'].text())):
                self._gum__seq_get_gumstick_read_avgtemp(sig_msg, "lineEdit_function_tt_A20")            
                time.sleep(int(self.FixedlineEdits['lineEdit_function_tt_A20_int'].text())/1000)

                if (x % int(self.FixedlineEdits['lineEdit_pll_count_per_interval'].text()) == 0): #1000ms * 30 = 30s
                    print("Start Pll Recalibration")
                    self.gumstick_seq_set_gumstick_pll_recal(sig_msg, "lineEdit_function_tt_A19")
        else:
            self._gum__seq_get_gumstick_read_avgtemp(sig_msg, "lineEdit_function_tt_A20")      
        self._sys_ui_unlock() 
       
    def gumstick_loop_get_gumstick_read_avgtemp_thread(self):     
        self._sys_thread_create(self.main_thread_group, 0, self._gum__loop_get_gumstick_read_avgtemp)

