    def gumstick_seq_tdd_ext_pin_enable(self, sig_msg):
        try:
            self._sys_tick_time_measure("self.gumstick_seq_tdd_ext_pin_enable", True)
            if sig_msg: 
                pass
            else:
                pass
            
            if(self.FixedButtons["pushButton_tdd_ext_pin_enable"].text() == "Sync Enable"):
                self.FixedButtons["pushButton_tdd_ext_pin_enable"].setText("Sync Disable") 
                self.FixedButtons["pushButton_tdd_ext_pin_enable"].setStyleSheet('QPushButton {background-color: #66FFFF; color: black;}')     
                self.gs.tdd_ext_pin_enable(1) 
                time.sleep(1)
                print("TDD Sync ext pin enabled!")
            else:
                self.FixedButtons["pushButton_tdd_ext_pin_enable"].setText("Sync Enable")                       
                self.FixedButtons["pushButton_tdd_ext_pin_enable"].setStyleSheet('QPushButton {background-color: #FFFF00; color: black;}') 
                self.gs.tdd_ext_pin_enable(0)
                time.sleep(1)
                print("TDD Sync ext pin disabled!")
        
            ret = self._sys_tick_time_measure("self.gumstick_seq_attenuation", False)
            if sig_msg: 
                pass
            else:
                pass
        except Exception as e:           
            print(self.getTracebackStr(traceback.format_exc()))
            return False   
        pass
    
    def gumstick_seq_tdd_init(self, sig_msg):
        self._sys_thread_create(self.main_thread_group, 0, self._gumstick_seq_tdd_init_th)  
                   
    def _gumstick_seq_tdd_init_th(self, sig_msg):  
        try:            
            self._sys_ui_lock()
            self.gs.tdd_init(self.FixedComboboxs['comboBox_beam'].currentText(), 
                               self.FixedComboboxs['comboBox_beam_pol'].currentText().lower(),
                               self.FixedComboboxs["comboBox_beam_mode"].currentText(),
                               int(self.FixedComboboxs["comboBox_beam_index"].currentText()),
                               int(self.FixedComboboxs['comboBox_tx_tdd_attenuation'].currentText()),
                               int(self.FixedComboboxs['comboBox_rx_tdd_attenuation'].currentText())
            )
                       
            self.gumstick_seq_tdd_attenuation(sig_msg)
            self.FixedButtons["pushButton_tdd_ext_pin_enable"].setText("Sync Enable")                       
            self.FixedButtons["pushButton_tdd_ext_pin_enable"].setStyleSheet('QPushButton {background-color: #FFFF00; color: black;}') 
            self.gs.tdd_ext_pin_enable(1) 
            time.sleep(1)
            self._sys_ui_unlock()
            return True         
        except Exception as e:
            self._sys_ui_unlock()           
            print(self.getTracebackStr(traceback.format_exc()))
            return False  
                  
    def gumstick_load_tx_phase_cal_file(self):    
        options = QFileDialog.Options()
        options |= QFileDialog.DontUseNativeDialog
        fileName, _ = QFileDialog.getOpenFileName(self, "QFileDialog.getOpenFileName()", self.default_init_path,
                                                    "Python Files (*.txt)", options=options)

        if fileName:
            self.Fixedlabels["label_load_tx_phase_cal_file_path"].setText(fileName)
        
        self.gs.load_phase_cal_from_file(txrx='tx', fname=fileName)

