    def gumstick_set_trx_settings_auto(self):       
        if (self.FixedCheckboxs['checkBox_power_tx_auto'].checkState() == self.CHECKED):
            self.__function_gum__tx_b1_auto()
            self.__function_gum__tx_b2_auto()

        if (self.FixedCheckboxs['checkBox_power_rx_auto'].checkState() == self.CHECKED):
            self.__function_gum__rx_b1_auto()
            self.__function_gum__rx_b2_auto()
    
    def gumstick_tx_on(self):     
        if (self.FixedCheckboxs['checkBox_power_tx_auto'].checkState() == self.CHECKED):
            self.__function_gum__tx_b1_auto()
            self.__function_gum__tx_b2_auto()
    
    def gumstick_rx_on(self):     
        if (self.FixedCheckboxs['checkBox_power_rx_auto'].checkState() == self.CHECKED):
            self.__function_gum__rx_b1_auto()
            self.__function_gum__rx_b2_auto()

    def gumstick_tx_off(self): 
        if (self.FixedCheckboxs['checkBox_power_tx_auto'].checkState() == self.CHECKED):
            self.gumstick_seq_config_tx_fe_all_off(None)
    
    def gumstick_rx_off(self):  
        if (self.FixedCheckboxs['checkBox_power_rx_auto'].checkState() == self.CHECKED):
            self.gumstick_seq_config_rx_fe_all_off(None)

