    def _gum__read_tssi_rssi_fe_all(self, sig_msg):
        try:
            self._sys_tick_time_measure("_gum__read_tssi_fe_all()", True)  
            
            beam = ['b1', 'b2']
            fe_idx = [0,1,2,3,4,5,6,7]
            fe_path = ['1h', '2h', '3h', '4h', '1v', '2v', '3v', '4v']
            count = int(self.FixedlineEdits['lineEdit_tssi_avg_cnt'].text()) 
            if_port = 'a' if self.FixedComboboxs['comboBox_txrx'].currentText() =='rx' else 'b'
                       
            print('\n** Read Mixer/Fe input/output tssi all **\n')  
            print('Start Temperature')
            self.gs.read_avgtemp()
                     
            for _, nBeam in enumerate(beam):
                              
                arr_mix_input_tssi = []
                arr_mix_input_tssi_mV = []
                arr_mix_input_tssi_dBm = []   
                arr_mix_output_tssi = []
                arr_mix_output_tssi_mV = []
                arr_mix_output_tssi_dBm = []
                   
                print('* MIXER Intput/Output')
                
                self.gs.read_avgtemp()      
                self.gs.mixer_clear_and_enable_block(blk = f"{nBeam}_if{if_port}", mode = "adc")
                for n in range(count):  
                    mix_input_tssi = self.gs.mixer_read_tssi()
                    mix_input_tssi_mV = self.gs.mixer_read_tssi_mV()
                    mix_input_tssi_dBm = round(10*math.log10(mix_input_tssi[0]/1000)*1.724+1.4655,2)  
                    arr_mix_input_tssi.append(mix_input_tssi[0])
                    arr_mix_input_tssi_mV.append(mix_input_tssi_mV[0])      
                    arr_mix_input_tssi_dBm.append(mix_input_tssi_dBm)    
                
                print(f'{nBeam}_if{if_port}, N/A, %s, dBm' % str(self.get_avg_val(arr_mix_input_tssi_dBm,2)))
                
                self.gs.mixer_clear_and_enable_block(blk = f"{nBeam}_txrf", mode = "adc")
                for n in range(count):
                    mix_output_tssi = self.gs.mixer_read_tssi()
                    mix_output_tssi_mV = self.gs.mixer_read_tssi_mV()
                    mix_output_tssi_dBm = round(10*math.log10(mix_output_tssi[0])*1.45-44,2)
                    arr_mix_output_tssi.append(mix_output_tssi[0])
                    arr_mix_output_tssi_mV.append(mix_output_tssi_mV[0])      
                    arr_mix_output_tssi_dBm.append(mix_output_tssi_dBm)    
                
                print(f'{nBeam}_txrf, N/A, %s, dBm' % str(self.get_avg_val(arr_mix_output_tssi_dBm,2)))
                
                for _, nFe_Idx in enumerate(fe_idx):  
                    
                    arr_fe_input_tssi_mV = []
                    arr_fe_input_tssi_dBm = []     
                    
                    print('* FE Input/Output')
                    self.gs.read_avgtemp() 
                    self.gs.fe_clear_and_enable_block(nFe_Idx, blk = f"{nBeam}_drv_tssi3", mode = "adc", clear_all = True)
                    
                    for n in range(count):                    
                        fe_input_tssi = self.gs.fe_read_tssi(nFe_Idx)
                        fe_input_tssi_mV = self.gs.fe_read_tssi_mV(nFe_Idx)
                        fe_input_tssi_dBm = round(10*math.log10(fe_input_tssi[0])*1.42-40,2)
                        arr_fe_input_tssi_mV.append(fe_input_tssi_mV[0])
                        arr_fe_input_tssi_dBm.append(fe_input_tssi_dBm)
                    #print(f'{nBeam}_drv_tssi3 : %s mV, %s dBm' % str(self.get_avg_val(arr_fe_input_tssi_mV,2)), str(self.get_avg_val(arr_fe_input_tssi_dBm,2)))
                    print(f'{nBeam}_drv_tssi3, N/A, %s, dBm' % str(self.get_avg_val(arr_fe_input_tssi_dBm,2)))
                    
                    for _, nFe_Path in enumerate(fe_path):  
                        
                        arr_fe_output_tssi_mV = []
                        arr_fe_output_tssi_dBm_high = []
                        arr_fe_output_tssi_dBm_low = [] 
                        
                        for n in range(count):
                            self.gs.fe_clear_and_enable_block(nFe_Idx, blk = f"fe{nFe_Path[0]}_{nFe_Path[1]}_tssi", mode = "adc", clear_all = True)
                            fe_output_tssi = self.gs.fe_read_tssi(nFe_Idx)
                            fe_output_tssi_mV = self.gs.fe_read_tssi_mV(nFe_Idx)
                            fe_output_tssi_dBm_high = round(10*math.log10(fe_output_tssi[0])*1.45-35,2)
                            fe_output_tssi_dBm_low = round(10*math.log10(fe_output_tssi[0])*1.45-38.5,2)
                                                                        
                            arr_fe_output_tssi_mV.append(fe_output_tssi_mV[0])
                            arr_fe_output_tssi_dBm_high.append(fe_output_tssi_dBm_high)      
                            arr_fe_output_tssi_dBm_low.append(fe_output_tssi_dBm_low)     
                    
                        print(f'fe{nFe_Idx}, fe{nFe_Path[0]}_{nFe_Path[1]}_tssi, %s, dBm' % str(self.get_avg_val(arr_fe_output_tssi_dBm_low,2)))
            
            print('Stop Temperature')
            self.gs.read_avgtemp()       
            self._sys_tick_time_measure("_gum__read_tssi_fe()", False)
            return True         
        except Exception as e:           
            print(self.getTracebackStr(traceback.format_exc()))
            return False

