    def _gum__gen_update_bbk_manager_beambook_tx(self, bbk_manager, array_simulator, theta_deg, phi_deg, beambook_index):
        coefs = array_simulator.calc_coefs_simple_steer(theta_deg, phi_deg, self.freq)
        temp_coef_filepath = os.path.join(bbk_manager.temp_folder, 'temp_coeffs_tx.txt')
        array_simulator.write_coeffs_to_file(coefs, temp_coef_filepath)

        if self.FixedCheckboxs['checkBox_using_tx_mvbeam_0_1_57'].checkState() == self.CHECKED:
            #for mvbeam-0.1.57-py3-none-any.whl
            bbk_manager.load_coefs_from_file(temp_coef_filepath, freq_ghz=self.freq_ghz, beam='b1', pol='h', beambook_index=beambook_index, ampl_update_mode = 1)
            bbk_manager.load_coefs_from_file(temp_coef_filepath, freq_ghz=self.freq_ghz, beam='b1', pol='v', beambook_index=beambook_index, ampl_update_mode = 1)
            bbk_manager.load_coefs_from_file(temp_coef_filepath, freq_ghz=self.freq_ghz, beam='b2', pol='h', beambook_index=beambook_index, ampl_update_mode = 1)
            bbk_manager.load_coefs_from_file(temp_coef_filepath, freq_ghz=self.freq_ghz, beam='b2', pol='v', beambook_index=beambook_index, ampl_update_mode = 1)
        else:
            bbk_manager.load_coefs_from_file(temp_coef_filepath, freq_ghz=self.freq_ghz, beam='b1', pol='h', beambook_index=beambook_index)
            bbk_manager.load_coefs_from_file(temp_coef_filepath, freq_ghz=self.freq_ghz, beam='b1', pol='v', beambook_index=beambook_index)
            bbk_manager.load_coefs_from_file(temp_coef_filepath, freq_ghz=self.freq_ghz, beam='b2', pol='h', beambook_index=beambook_index)
            bbk_manager.load_coefs_from_file(temp_coef_filepath, freq_ghz=self.freq_ghz, beam='b2', pol='v', beambook_index=beambook_index)

    def _gum__gen_update_bbk_manager_beambook_rx(self, bbk_manager, array_simulator, theta_deg, phi_deg, beambook_index):
        coefs = array_simulator.calc_coefs_simple_steer(theta_deg, phi_deg, self.freq)
        temp_coef_filepath = os.path.join(bbk_manager.temp_folder, 'temp_coeffs_rx.txt')
        array_simulator.write_coeffs_to_file(coefs, temp_coef_filepath)

        if self.FixedCheckboxs['checkBox_using_rx_mvbeam_0_1_57'].checkState() == self.CHECKED:            
            #for mvbeam-0.1.57-py3-none-any.whl
            bbk_manager.load_coefs_from_file(temp_coef_filepath, freq_ghz=self.freq_ghz, beam='b1', pol='h', beambook_index=beambook_index, ampl_update_mode = 1)
            bbk_manager.load_coefs_from_file(temp_coef_filepath, freq_ghz=self.freq_ghz, beam='b1', pol='v', beambook_index=beambook_index, ampl_update_mode = 1)
            bbk_manager.load_coefs_from_file(temp_coef_filepath, freq_ghz=self.freq_ghz, beam='b2', pol='h', beambook_index=beambook_index, ampl_update_mode = 1)
            bbk_manager.load_coefs_from_file(temp_coef_filepath, freq_ghz=self.freq_ghz, beam='b2', pol='v', beambook_index=beambook_index, ampl_update_mode = 1)
        else:
            bbk_manager.load_coefs_from_file(temp_coef_filepath, freq_ghz=self.freq_ghz, beam='b1', pol='h', beambook_index=beambook_index)
            bbk_manager.load_coefs_from_file(temp_coef_filepath, freq_ghz=self.freq_ghz, beam='b1', pol='v', beambook_index=beambook_index)
            bbk_manager.load_coefs_from_file(temp_coef_filepath, freq_ghz=self.freq_ghz, beam='b2', pol='h', beambook_index=beambook_index)
            bbk_manager.load_coefs_from_file(temp_coef_filepath, freq_ghz=self.freq_ghz, beam='b2', pol='v', beambook_index=beambook_index)
     
    def _sequence_a_process(self, sig_msg):  
        try:             
            ret = True

            self._sys_ui_lock()
            if not self.delete_ds_log: print('Start the sequence A!')
             
            self._sys_test_time_measure("_sequence_a_process()", True)  

            try:
                self.gumstick_seq_gumstick(sig_msg, "")
                self.gumstick_seq_init(sig_msg, "")
                #self.gumstick_seq_digital_test(sig_msg, "")
                self.gumstick_seq_init_vcxo_pll(sig_msg, "")
                self.gumstick_seq_set_rf(sig_msg, "")
                self.gumstick_seq_set_mixer(sig_msg, "", self.FixedComboboxs['comboBox_txrx'].currentText(), self.FixedComboboxs["comboBox_tx_band"].currentText(), self.mv2850_frequency['lo_mix'][self.Hz], self.mv2850_frequency['if'][self.Hz])                
                self.gumstick_seq_set_pll(sig_msg, "", self.mv2850_frequency['pll_out'][self.MHz])
                self.gumstick_seq_run_load_beam_book_from_flash(sig_msg, "")    
                self.gs.reset_mirror()                     
                self.gumstick_seq_set_txrx(sig_msg, "", self.FixedComboboxs['comboBox_txrx'].currentText(), self.FixedComboboxs['comboBox_beam'].currentText(), self.FixedComboboxs["comboBox_tx_band"].currentText())
                self.gumstick_seq_config_tx_fe_all_off(sig_msg, "")
                self.gumstick_seq_config_rx_fe_all_off(sig_msg, "")
                #self.gumstick_seq_set_beam_mode(sig_msg, "", self.FixedComboboxs['comboBox_txrx'].currentText(), self.FixedComboboxs["comboBox_beam_mode"].currentText(), self.FixedComboboxs['comboBox_beam'].currentText(), self.FixedComboboxs['comboBox_beam_pol'].currentText().lower())
                #self.gumstick_seq_set_beam_index(sig_msg, "", self.FixedComboboxs['comboBox_txrx'].currentText(), self.FixedComboboxs['comboBox_beam'].currentText(), self.FixedComboboxs['comboBox_beam_pol'].currentText().lower(), self.FixedComboboxs["comboBox_beam_index"].currentText())
                #self.gumstick_seq_set_init_RX_IQ(sig_msg, "")
                #self.gumstick_seq_init_gain(sig_msg, "")
                self.gumstick_seq_set_gumstick_pll_recal(sig_msg, "")
                self.gumstick_seq_attenuation(sig_msg, "")
                self._gum__loop_get_gumstick_read_avgtemp(sig_msg)

            except Exception as e:
                print(self.getTracebackStr(traceback.format_exc()))
                
            ret = self._sys_test_time_measure("_sequence_a_process()", False) 
                
            if not self.delete_ds_log: print("_sequence_a_process done!")
            self._sys_ui_unlock()
            return True         
        except Exception as e:           
            self._sys_ui_unlock()
            print(self.getTracebackStr(traceback.format_exc()))
            return False    
     
    def _sys_ui_lock(self):
        self.FixedWidgets['tabWidget_main'].setEnabled(False)

    def _sys_ui_unlock(self):
        self.FixedWidgets['tabWidget_main'].setEnabled(True)

    def _sys_write_registry_information(self, name, note):
        try:
            Key1 = winreg.CreateKey(winreg.HKEY_CURRENT_USER, self.net_name)
            Key4 = winreg.CreateKey(winreg.HKEY_CURRENT_USER, self.net_note)

            winreg.SetValueEx(Key1, "name", 0, winreg.REG_SZ, name)
            winreg.SetValueEx(Key4, "note", 0, winreg.REG_SZ, note)

        except Exception as e:
            print(self.getTracebackStr(traceback.format_exc()))
            pass

    @pyqtSlot(str, str, str)
    def _sys_msg_handler(self, msg_type: str, msg_name: str, msg: str):
        #print(msg_type + ", " + msg_name + ", " + msg)
        if msg_type == "FixedlineEdits":
            self.FixedlineEdits[msg_name].setText(msg)
        elif msg_type == "Fixedlabels":
            self.Fixedlabels[msg_name].setText(msg)
        elif msg_type == "textboxes":
            self.textboxes[msg_name].setText(msg)
        elif msg_type == "FixedButtons":            
            for x in range(0, 58):  
                self.FixedButtons["pushButton_beam_%s"%x].setStyleSheet('QPushButton {background-color: #66FFFF; color: black;}')            
            self.FixedButtons[msg_name].setStyleSheet('QPushButton {background-color: #FFFF00; color: black;}') 
            pass
            
        #self.textEdit_log.append(msg_type + ", " + msg_name + ", " + msg)
        
    def _sys_thread_create(self, thread, id, func):
        try:
            thread[id] = UserthreadSingleTask(self, func)
            thread[id].daemon = True
            thread[id].sig_msg.connect(self._sys_msg_handler)
            thread[id].start()
            return True         
        except Exception as e:
            print(self.getTracebackStr(traceback.format_exc()))
            return False

    def _sys_thread_create_close(self, thread, id):
        try:
            if thread[id]:
                #thread[0].stop()
                thread[id].terminate()
                thread[id].wait()
                thread[id] = 0
            self._sys_ui_unlock()
            return True         
        except Exception as e:
            print(self.getTracebackStr(traceback.format_exc()))
            return False

    def _sys_create_loop_thread(self, thread, id, func):
        try:
            thread[id] = UserthreadLoopTask(self, func)
            thread[id].daemon = True
            thread[id].sig_msg.connect(self._sys_msg_handler)
            thread[id].start()
            return True         
        except Exception as e:
            print(self.getTracebackStr(traceback.format_exc()))
            return False

    def _sys_close_loop_thread(self, thread, id):
        try:
            if thread[id]:
                #thread[id].stop()
                thread[id].terminate()
                thread[id].wait()
                thread[id] = 0
            self._sys_ui_unlock()
            return True         
        except Exception as e:
            print(self.getTracebackStr(traceback.format_exc()))
            return False

    def _sys_create_serial_thread(self):
        try:
            if self._connect_port:
                if self._ser_t == 0:
                    self._ser_t = serial_t.ReaderThread(self._ser, serial_t.rawProtocal)
                    self._ser_t.start()
                    self._ser_t.protocol_factory.get_obj(self._ser_t.protocol_factory, self)
                    time.sleep(0.1)
                    return True
                else:
                    return False
            else:
                if not self.delete_ds_log: print('create serial error!')
                return False
        except Exception as e:
            print(self.getTracebackStr(traceback.format_exc()))
            return False

    def _sys_close_serial_thread(self):
        try:
            if self._connect_port:
                if self._ser_t:
                    self._ser_t.stop()
                    time.sleep(0.2)
                    self._ser_t.close()
                    self._ser_t = 0
                if self._ser:
                    self._ser.close()
                    self._ser = 0
                return True
            else:
                if not self.delete_ds_log: print('destroy serial error!')
                return False
        except Exception as e:
            print(self.getTracebackStr(traceback.format_exc()))
            return False

    def _sys_define_set(self):    
        self.CHECKED = 2
        self.UNCHECKED = 0
        self.MHz = 0
        self.Hz = 1

    def _tescom_function_check_port(self):
        try:
            key = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, "HARDWARE\\DEVICEMAP\\SERIALCOMM")
            i = 0
            while True:
                subkey = winreg.EnumValue(key, i)
                self.ComportBox.addItem(subkey[1])
                i += 1
                time.sleep(0.001)
            return True         
        except Exception as e:
            #print(self.getTracebackStr(traceback.format_exc()))
            return False

    def _testcom_function_is_open(self):
        return self._connect_port

    def _tescom_function_port_connect(self):
        port = self.ComportBox.currentText()
        baud_rate = self.BaudrateBox.currentText()

        try:
            self._ser = serial_t.serial.serial_for_url(port, baudrate=baud_rate, timeout=5)
            if self._ser.is_open:
                self._connect_port = True
                if self._sys_create_serial_thread():
                    self.FixedButtons['pushButton_tescom_Port_Disconnect'].setEnabled(True)
                    self.FixedButtons['pushButton_tescom_Port_Connect'].setEnabled(False)
                    return True
                else:
                    if not self.delete_ds_log: print('port open error!')
                    self._connect_port = False
                    return False
            else:
                if not self.delete_ds_log: print('port open error!')
                self._connect_port = False
                return False
        except SerialException as e:
            if not self.delete_ds_log: print('port_connect except :', str(e))
            return False

    def _tescom_function_port_disconnect(self):
        try:
            if self._connect_port:
                if self._sys_close_serial_thread():
                    self.FixedButtons['pushButton_tescom_Port_Connect'].setEnabled(True)
                    self.FixedButtons['pushButton_tescom_Port_Disconnect'].setEnabled(False)
                    self._connect_port = False
                    return True
                else:
                    if not self.delete_ds_log: print('port disconnected error!')
                    return False
            else:
                if not self.delete_ds_log: print('already port disconnect!')
                return False
        except Exception as e:
            print(self.getTracebackStr(traceback.format_exc()))
            return False

