    def _init_mainlayouts_2d_rotate_graphics_initialize(self):   
        self.grPlot_tescom_rotate_test.showGrid(True, True, 0.5)
        self.grPlot_tescom_rotate_test.addLegend(size=None)
        self.grPlot_tescom_rotate_test.setXRange(int(self.FixedSpinboxs['spinBox_start_elevation'].value())-90, int(self.FixedSpinboxs['spinBox_stop_elevation'].value())-90)
        self.grPlot_tescom_rotate_test.setYRange(-60, 60)
        self.grPlot_tescom_rotate_test.setLabel("left", text="Pout", units="dBm")
        self.grPlot_tescom_rotate_test.setLabel('bottom', text="Rotator Angle", units="deg")
        self.plotData_tescom = {'x': [], 'y': []}
        self.pdi_tescom = []
        self.pdi_count = Count()
        self.pdi_tescom.append(self.grPlot_tescom_rotate_test.plot(name="plot id is " + str(self.pdi_count.val)))
        
    def _function_drawing_rotate_graphics(self, idx, x, y, delete):
        #temp = 'idx: ' + str(idx) + ', x: ' + str(x) + ', y: ' + str(y)      
        if (delete == True):
            pass
        else:
            self.plotData_tescom['x'].append(float(x)) 
            self.plotData_tescom['y'].append(float(y)) 

        self.pdi_tescom[idx].setData(self.plotData_tescom['x'], self.plotData_tescom['y'], pen=pg.mkPen('b', wiDSh=3))       
        if (delete == True):
            pass    
        else:
            self.grPlot_tescom_rotate_test.setYRange(max(self.plotData_tescom['y'][0:len(self.plotData_tescom['y'])]) + 5, min(self.plotData_tescom['y'][0:len(self.plotData_tescom['y']):]) - 5)     

    def _function_rotate_measurement(self):   
        self._sys_test_time_measure("_function_rotate_measurement()", True)  
         
        # IF Measurement Settings
        if self.ins[self._inst_get_current_if()[0]].is_connect() or self.simulation: 
            self.selected_if_index = self._inst_get_current_if()[0]
            pass
        else:
            if not self.delete_ds_log: print("%s is not connected!" % (self._inst_get_current_if()[1]))
            return
            
        # RF Measurement Settings
        if self.ins[self._inst_get_current_rf()[0]].is_connect() or self.simulation:  
            self.selected_rf_index = self._inst_get_current_rf()[0]
            pass
        else:
            if not self.delete_ds_log: print("%s is not connected!" % (self._inst_get_current_rf()[1]))
            return

        # Gumstick Settings
        if self.simulation: 
            pass
        else:   
            if not self.delete_ds_log: print("MVBX is not connected!")   

        try:            
            if self._testcom_function_is_open():            
                self.default_log_path = os.path.dirname(os.path.realpath(__file__)) + '\\Logs'            
                if not (os.path.isdir(self.default_log_path)):
                    os.makedirs(os.path.join(self.default_log_path))                
                self.logtimestr = time.strftime("%Y%m%d-%H%M%S")
            
                if(self.f_meas): 
                    self.f_meas.close()
                    self.f_meas = 0
                path = self.default_log_path + '\\' + self.logtimestr + '_' + self.textboxes["init_name"].text() + '_' + self.textboxes["init_note"].text() + '_' + self.mode + '_rotator' + '.csv'
                self.f_meas = open(path, 'w+')
                self.f_meas.write('%s,%s,%s\n' % ("MODE", "DEGREE", "POUT"))

                if self.mode == "azimuth":  
                    self._tescom_function_45_degree()
                    time.sleep(3)

                    self.ins[self.selected_if_index].set_parameter(self.ins_mode.CONTINUOUS, self._inst_update_parameter(self.selected_if_index)) 
                    self.ins[self.selected_if_index].set_sg(self.ins_port.IF, self.ins_mode.CONTINUOUS)
                    self.ins[self.selected_if_index].set_modulation(self.ins_port.IF, "OFF")      
                    self.ins[self.selected_if_index].set_rf(self.ins_port.IF, "ON")  
                    self.ins[self.selected_if_index].set_output_power(self.ins_port.IF, str(self.FixedSpinboxs['spinBox_output_level_azimuth'].value()))  # Pin (dBm)

                    # Should be check the remote language("SCPI") of ms2850 system settings. 
                    self.ins[self.selected_rf_index].set_parameter(self.ins_mode.CONTINUOUS, self._inst_update_parameter(self.selected_rf_index)) 
                    self.ins[self.selected_rf_index].set_sa(self.ins_port.RF, self.ins_mode.CONTINUOUS)

                    for x in range(int(self.FixedSpinboxs['spinBox_start_azimuth'].value()), int(self.FixedSpinboxs['spinBox_stop_azimuth'].value())+1): #45 ~ 135            
                        temp = 'AT-MOTCTRL=1,'+str(x)+','+str(self.FixedSpinboxs['spinBox_azimuth'].value())+'\r\n'                
                        self._ser_t.write(temp.encode('utf-8'))                
                        time.sleep(0.3)                    
                        ret = self.ins[self.selected_rf_index].measure_start(self.ins_port.RF, int(self.textboxes["Measure_capture_cnt"].text()), 0)
                        self.ins[self.selected_rf_index].measure_stop() 
                        
                        if ret:
                            measure = ret.replace('\r', '').replace('\n', '')
                            results = 'Azimuth, '+ str(x)+', '+measure+','
                            self.f_meas.write('%s\n' % (results))
                        #results = uniform(-30.0, 60.0)
                        self._function_drawing_rotate_graphics(self.pdi_count.val, x-90, measure, False)
                        if not self.delete_ds_log: print(results)  
                        
                elif self.mode == "elevation":  
                    self._tescom_function_45_degree()
                    time.sleep(3)

                    self.ins[self.selected_if_index].set_parameter(self.ins_mode.CONTINUOUS, self._inst_update_parameter(self.selected_if_index)) 
                    self.ins[self.selected_if_index].set_sg(self.ins_port.IF, self.ins_mode.CONTINUOUS)
                    self.ins[self.selected_if_index].set_modulation(self.ins_port.IF, "OFF")      
                    self.ins[self.selected_if_index].set_rf(self.ins_port.IF, "ON")  
                    self.ins[self.selected_if_index].set_output_power(self.ins_port.IF, str(self.FixedSpinboxs['spinBox_output_level_elevation'].value()))  # Pin (dBm)

                    # Should be check the remote language("SCPI") of ms2850 system settings.
                    self.ins[self.selected_rf_index].set_parameter(self.ins_mode.CONTINUOUS, self._inst_update_parameter(self.selected_rf_index)) 
                    self.ins[self.selected_rf_index].set_sa(self.ins_port.RF, self.ins_mode.CONTINUOUS)

                    for x in range(int(self.FixedSpinboxs['spinBox_start_elevation'].value()), int(self.FixedSpinboxs['spinBox_stop_elevation'].value())+1): #45 ~ 135            
                        temp = 'AT-MOTCTRL=1,'+str(x)+','+str(self.FixedSpinboxs['spinBox_azimuth'].value())+'\r\n'                
                        self._ser_t.write(temp.encode('utf-8'))                                
                        time.sleep(0.3)                
                        ret = self.ins[self.selected_rf_index].measure_start(self.ins_port.RF, int(self.textboxes["Measure_capture_cnt"].text()), 0) 
                        self.ins[self.selected_rf_index].measure_stop() 
                        
                        if ret:
                            measure = ret.replace('\r', '').replace('\n', '')
                            results = 'Azimuth, '+ str(x)+', '+measure+','  
                            self.f_meas.write('%s\n' % (results))
                        #results = uniform(-30.0, 60.0)
                        self._function_drawing_rotate_graphics(self.pdi_count.val, x-90, measure, False)
                        if not self.delete_ds_log: print(results) 

                #self._function_exporter_image_save_as_png(self.default_log_path, self.textboxes["init_name"].text() + '_' + self.textboxes["init_note"].text() + '_' + self.mode + '_rotator', self.grPlot_tescom_rotate_test)

            else:
                if not self.delete_ds_log: print("tescom rotator is not connected!") 

            if self.f_meas: 
                self.f_meas.close()
                self.f_meas = 0
            self._sys_test_time_measure("_function_rotate_measurement()", False)  

        except Exception as ex:
            if not self.delete_ds_log: print(ex)    
            if self.f_meas: 
                self.f_meas.close()
                self.f_meas = 0 
            print(self.getTracebackStr(traceback.format_exc()))

