    def _chip__port_scan(self, sig_msg = None):
        #print("_chip__port_scan")
        self.comboBox_chp_port.clear()
       
        try:
            key = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, "HARDWARE\\DEVICEMAP\\SERIALCOMM")
            i = 0
            while True:
                subkey = winreg.EnumValue(key, i)
                # print(subkey)
                
                if(subkey[0].find("VCP1")>0):                
                    self.comboBox_chp_port.addItem(subkey[1])
                i += 1
                time.sleep(0.001)
            return True         
        except Exception as e:
            #print(self.getTracebackStr(traceback.format_exc()))
            return False
    
