    def _chip__set_frequency(self, sig_msg):
        self.chip_if_freq_val = float(self.FixedlineEdits["lineEdit_chip_if_1"].text())             # 5000 MHz        
        #self.chip_rf_val = float(self.FixedlineEdits["lineEdit_chip_rf_2"].text())                 # 28.0e9 Hz                                                                                    
        self.chip_rf_val = float(self.FixedlineEdits["lineEdit_chip_rf_1"].text())                  # 27.5 MHz   
        self.chip_ref_clock_val = float(self.FixedlineEdits["lineEdit_chip_ref_clock_1"].text())    # 122.88 MHz
        self._chip_set_frequency_calculator()
                
    def _chip_set_frequency_calculator(self, sig_msg = None):
        self.chip_lo_mix_Hz_val = self.chip_rf_val * pow(10,6) - self.chip_if_freq_val * pow(10,6)
        self.chip_pll_out_Hz_val = self.chip_lo_mix_Hz_val / 3

        self.chip_frequency = {'pll_out' : [self.chip_pll_out_Hz_val / pow(10,6), self.chip_pll_out_Hz_val,],     # MHz , Hz
                                'lo_mix' : [self.chip_lo_mix_Hz_val / pow(10,6), self.chip_lo_mix_Hz_val],        # MHz , Hz
                                'rf' : [self.chip_rf_val, self.chip_rf_val * pow(10,6)],                          # MHz , Hz
                                'if' : [self.chip_if_freq_val, self.chip_if_freq_val * pow(10,6)],                # MHz , Hz
                                'ref_clock' : [self.chip_ref_clock_val, self.chip_ref_clock_val * pow(10,6)]}     # MHz , Hz

        if sig_msg:
            sig_msg.emit("FixedlineEdits", "lineEdit_chip_pll_out_1", str(self.chip_frequency['pll_out'][self.MHz]))
            sig_msg.emit("FixedlineEdits", "lineEdit_chip_pll_out_2", str(self.chip_frequency['pll_out'][self.Hz]))
            sig_msg.emit("FixedlineEdits", "lineEdit_chip_lo_mix_1", str(self.chip_frequency['lo_mix'][self.MHz]))
            sig_msg.emit("FixedlineEdits", "lineEdit_chip_lo_mix_2", str(self.chip_frequency['lo_mix'][self.Hz]))
            sig_msg.emit("FixedlineEdits", "lineEdit_chip_rf_1", str(self.chip_frequency['rf'][self.MHz]))
            sig_msg.emit("FixedlineEdits", "lineEdit_chip_rf_2", str(self.chip_frequency['rf'][self.Hz]))
            sig_msg.emit("FixedlineEdits", "lineEdit_chip_if_1", str(self.chip_frequency['if'][self.MHz]))
            sig_msg.emit("FixedlineEdits", "lineEdit_chip_if_2", str(self.chip_frequency['if'][self.Hz]))
            sig_msg.emit("FixedlineEdits", "lineEdit_chip_ref_clock_1", str(self.chip_frequency['ref_clock'][self.MHz]))
            sig_msg.emit("FixedlineEdits", "lineEdit_chip_ref_clock_2", str(self.chip_frequency['ref_clock'][self.Hz]))
        else:
            self.FixedlineEdits["lineEdit_chip_pll_out_1"].setText(str(self.chip_frequency['pll_out'][self.MHz]))
            self.FixedlineEdits["lineEdit_chip_pll_out_2"].setText(str(self.chip_frequency['pll_out'][self.Hz]))
            self.FixedlineEdits["lineEdit_chip_lo_mix_1"].setText(str(self.chip_frequency['lo_mix'][self.MHz]))
            self.FixedlineEdits["lineEdit_chip_lo_mix_2"].setText(str(self.chip_frequency['lo_mix'][self.Hz]))
            self.FixedlineEdits["lineEdit_chip_rf_1"].setText(str(self.chip_frequency['rf'][self.MHz]))
            self.FixedlineEdits["lineEdit_chip_rf_2"].setText(str(self.chip_frequency['rf'][self.Hz]))
            self.FixedlineEdits["lineEdit_chip_if_1"].setText(str(self.chip_frequency['if'][self.MHz]))
            self.FixedlineEdits["lineEdit_chip_if_2"].setText(str(self.chip_frequency['if'][self.Hz]))
            self.FixedlineEdits["lineEdit_chip_ref_clock_1"].setText(str(self.chip_frequency['ref_clock'][self.MHz]))
            self.FixedlineEdits["lineEdit_chip_ref_clock_2"].setText(str(self.chip_frequency['ref_clock'][self.Hz]))
        
        if self.chip_frequency['rf'][self.Hz] < chip_control().frequency_limit['Low'][0]:
            self.FixedComboboxs["comboBox_chip_tx_band"].setCurrentIndex(0)
        elif self.chip_frequency['rf'][self.Hz] >= chip_control().frequency_limit['Low'][0] and self.chip_frequency['rf'][self.Hz] <= chip_control().frequency_limit['High'][0]:
            self.FixedComboboxs["comboBox_chip_tx_band"].setCurrentIndex(1)
        else:
            self.FixedComboboxs["comboBox_chip_tx_band"].setCurrentIndex(2)
        
