    def _chip__pavt_load_result(self, sig_msg):
        #if not self.delete_ds_log: print("_chip__pavt_load_result")
        
        # C:\Users\seyoung4.park\Desktop
        # path = os.path.expanduser('~') + "\\Desktop"
        # Documents\NI-RFmx SFP Data
        # path = os.path.expanduser('~') + "\\Documents\\NI-RFmx SFP Data"
        path = "C:\\Users\\Public\\Documents\\NI-RFmx SFP Data"
        
        options = QFileDialog.Options()
        options |= QFileDialog.DontUseNativeDialog
        fileName, _ = QFileDialog.getOpenFileName(self, "QFileDialog.getOpenFileName()", path, "Csv Files (*.csv)", options=options)
            
        PA_array = []                                          
        if fileName:
            #print(fileName, _)
            f = open(fileName, 'r', encoding='utf-8')
            rdr = csv.reader(f)
            record = False
            i = 0
            for line in rdr:
                if(line):
                    if(line[0] == 'Segment'):
                        record = True                        
                    elif(line[0] == 'Trace'):
                        break
                    if(record):
                        if(line[0] != 'Segment'):
                            PA_array.append(line[:5])
                            i = i+1
            f.close()
            
            if self.FixedCheckboxs["checkBox_chip_pavt_re_adjustment"].checkState() == self.CHECKED: 
                adjust = True
            else:
                adjust = False
            
            gain_index_arry, phase_offset = self.chip.PAvT_result(np.ravel(PA_array).astype(float), 
                                                                  Count = 8,
                                                                  gain = np.ravel(self.FixedlineEdits['lineEdit_chip_pavt_gain_index'].text().split(',')).astype(int),
                                                                  ps = np.ravel(self.FixedlineEdits['lineEdit_chip_pavt_phase_index'].text().split(',')).astype(int),
                                                                  adjust = adjust)
            self.FixedlineEdits['lineEdit_chip_pavt_gain_index'].setText(','.join(str(s) for s in gain_index_arry))
            self.FixedlineEdits['lineEdit_chip_pavt_phase_index'].setText(','.join(str(s) for s in phase_offset))   
                      
    def _chip_loop_read_avgtemp(self, sig_msg):
        try:
            self._sys_tick_time_measure("self._chip_loop_read_avgtemp", True)
            if sig_msg: 
                sig_msg.emit("FixedlineEdits", "lineEdit_function_chip_temp_tt", "")
            else:
                self.FixedlineEdits['lineEdit_function_chip_temp_tt'].setText("") 
                
            mix_temp, fe_temp = self.chip.temp()
            if sig_msg:
                sig_msg.emit("FixedlineEdits", "lineEdit_chip_temp_feavg", str("%.3f"%(fe_temp)))            
                sig_msg.emit("FixedlineEdits", "lineEdit_chip_temp_mixeravg", str("%.3f"%(mix_temp)))
                pass
            else:      
                self.FixedlineEdits["lineEdit_chip_temp_feavg"].setText(str("%.3f"%(fe_temp)))
                self.FixedlineEdits["lineEdit_chip_temp_mixeravg"].setText(str("%.3f"%(mix_temp)))
            
            ret = self._sys_tick_time_measure("self._chip_loop_read_avgtemp", False)
            if sig_msg: 
                sig_msg.emit("FixedlineEdits", "lineEdit_function_chip_temp_tt", ret)
            else:
                self.FixedlineEdits['lineEdit_function_chip_temp_tt'].setText(str(ret))
                
                
        except Exception as e:           
            print(self.getTracebackStr(traceback.format_exc()))
            return False   
                
    def _chip__read_temp_th(self, sig_msg):  
        try:            
            self._sys_ui_lock()  
            if int(self.FixedlineEdits['lineEdit_function_chip_temp_cnt'].text()) > 1:             
                print("Temp. Loop Count\t= cnt", int(self.FixedlineEdits['lineEdit_function_chip_temp_cnt'].text())) 
                print("Temp. Loop Interval(s)\t=", int(self.FixedlineEdits['lineEdit_function_chip_temp_int'].text())/1000)          
                for x in range(0, int(self.FixedlineEdits['lineEdit_function_chip_temp_cnt'].text())):
                    self._chip_loop_read_avgtemp(sig_msg)        
                    time.sleep(int(self.FixedlineEdits['lineEdit_function_chip_temp_int'].text())/1000)
            else:
                self._chip_loop_read_avgtemp(sig_msg)       
            
            self._sys_ui_unlock()
            return True         
        except Exception as e:
            self._sys_ui_unlock()           
            print(self.getTracebackStr(traceback.format_exc()))
            return False
        
