    def _chip__read_tssi_fe_th(self, sig_msg):  
        try:            
            self._sys_ui_lock()  
            
            input = self.chip.get_fe_intput_tssi(beam = self.FixedComboboxs['comboBox_chip_beam'].currentText())
            input_dBm = round(10*math.log10(input)*1.42-40,2)
            output = self.chip.get_fe_output_tssi(fe_path = self.FixedComboboxs['comboBox_chip_tssi_fe_path'].currentText())
            output_dBm = round(10*math.log10(output)*1.42-40,2)
               
            if sig_msg: 
                sig_msg.emit("FixedlineEdits", "lineEdit_chip_fe_input_tssi_mV", str("%.3f"%(input)))
                sig_msg.emit("FixedlineEdits", "lineEdit_chip_fe_output_tssi_mV", str("%.3f"%(output)))                
                sig_msg.emit("FixedlineEdits", "lineEdit_chip_fe_input_tssi_dBm", str("%.3f"%(input_dBm)))
                sig_msg.emit("FixedlineEdits", "lineEdit_chip_fe_output_tssi_dBm", str("%.3f"%(output_dBm)))
            else:
                self.FixedlineEdits['lineEdit_chip_fe_input_tssi_mV'].setText(str("%.3f"%(input)))
                self.FixedlineEdits['lineEdit_chip_fe_output_tssi_mV'].setText(str("%.3f"%(output)))                
                self.FixedlineEdits['lineEdit_chip_fe_input_tssi_dBm'].setText(str("%.3f"%(input_dBm)))
                self.FixedlineEdits['lineEdit_chip_fe_output_tssi_dBm'].setText(str("%.3f"%(output_dBm)))
            
            self._sys_ui_unlock()
            return True         
        except Exception as e:
            self._sys_ui_unlock()           
            print(self.getTracebackStr(traceback.format_exc()))
            return False
       
