    def _chip__array_on(self, sig_msg, array):
        
        if(self.FixedButtons["pushButton_chip_%s"%array].text() == "Off"):
            self.FixedButtons["pushButton_chip_%s"%array].setStyleSheet('QPushButton {background-color: #FFFF00; color: black;}')  
            self.FixedButtons["pushButton_chip_%s"%array].setText("On")
            self.chip.config_FE_TRX(self.FixedComboboxs['comboBox_txrx'].currentText(), "%s_%s"%(self.FixedComboboxs['comboBox_chip_beam'].currentText(),array))
        #else:  
        #    self.FixedButtons["pushButton_chip_%s"%array].setStyleSheet('QPushButton {background-color: #66FFFF; color: black;}')  
        #    self.FixedButtons["pushButton_chip_%s"%array].setText("Off")
               
    def _chip__array_hv_on(self, sig_msg, array):        
        if(array == '1'):
            self._chip__array_on(sig_msg, "1h")
            self._chip__array_on(sig_msg, "1v")
        elif(array == '2'):
            self._chip__array_on(sig_msg, "2h")
            self._chip__array_on(sig_msg, "2v")
        elif(array == '3'):
            self._chip__array_on(sig_msg, "3h")
            self._chip__array_on(sig_msg, "3v")
        elif(array == '4'):
            self._chip__array_on(sig_msg, "4h")
            self._chip__array_on(sig_msg, "4v") 
                        
    def _chip__all_on(self, sig_msg, status):
        if (status == "h_all"):
            for x in range(1, 5): 
                self.FixedButtons["pushButton_chip_%sh"%x].setStyleSheet('QPushButton {background-color: #FFFF00; color: black;}')  
                self.FixedButtons["pushButton_chip_%sh"%x].setText("On") 
                #b1_1h
                self.chip.config_FE_TRX(self.FixedComboboxs['comboBox_txrx'].currentText(), "%s_%s"%(self.FixedComboboxs['comboBox_chip_beam'].currentText(),'1h'))
                self.chip.config_FE_TRX(self.FixedComboboxs['comboBox_txrx'].currentText(), "%s_%s"%(self.FixedComboboxs['comboBox_chip_beam'].currentText(),'2h'))
                self.chip.config_FE_TRX(self.FixedComboboxs['comboBox_txrx'].currentText(), "%s_%s"%(self.FixedComboboxs['comboBox_chip_beam'].currentText(),'3h'))
                self.chip.config_FE_TRX(self.FixedComboboxs['comboBox_txrx'].currentText(), "%s_%s"%(self.FixedComboboxs['comboBox_chip_beam'].currentText(),'4h'))
        elif (status == "v_all"):
            for x in range(1, 5): 
                self.FixedButtons["pushButton_chip_%sv"%x].setStyleSheet('QPushButton {background-color: #FFFF00; color: black;}') 
                self.FixedButtons["pushButton_chip_%sv"%x].setText("On") 
                #b1_1v
                self.chip.config_FE_TRX(self.FixedComboboxs['comboBox_txrx'].currentText(), "%s_%s"%(self.FixedComboboxs['comboBox_chip_beam'].currentText(),'1v'))
                self.chip.config_FE_TRX(self.FixedComboboxs['comboBox_txrx'].currentText(), "%s_%s"%(self.FixedComboboxs['comboBox_chip_beam'].currentText(),'2v'))
                self.chip.config_FE_TRX(self.FixedComboboxs['comboBox_txrx'].currentText(), "%s_%s"%(self.FixedComboboxs['comboBox_chip_beam'].currentText(),'3v'))
                self.chip.config_FE_TRX(self.FixedComboboxs['comboBox_txrx'].currentText(), "%s_%s"%(self.FixedComboboxs['comboBox_chip_beam'].currentText(),'4v'))
        else:
            for x in range(1, 5): 
                if(status == "On"):
                    self.FixedButtons["pushButton_chip_%sh"%x].setStyleSheet('QPushButton {background-color: #FFFF00; color: black;}')  
                    self.FixedButtons["pushButton_chip_%sv"%x].setStyleSheet('QPushButton {background-color: #FFFF00; color: black;}')  
                else:
                    self.FixedButtons["pushButton_chip_%sh"%x].setStyleSheet('QPushButton {background-color: #66FFFF; color: black;}')  
                    self.FixedButtons["pushButton_chip_%sv"%x].setStyleSheet('QPushButton {background-color: #66FFFF; color: black;}')  
                self.FixedButtons["pushButton_chip_%sh"%x].setText(status) 
                self.FixedButtons["pushButton_chip_%sv"%x].setText(status)
        
            if(status == "On"):
                self.chip.config_FE_TRX(self.FixedComboboxs['comboBox_txrx'].currentText(), 'all_on')
            else:
                self.chip.config_FE_TRX(self.FixedComboboxs['comboBox_txrx'].currentText(), 'all_off')
                       
    def _chip__run(self, sig_msg):
        self._sys_thread_create(self.main_thread_group, 0, self._chip__run_process)  
       
    def _chip__run_process(self, sig_msg):  
        try:             
            self._sys_ui_lock()
            self._sys_test_time_measure("_chip__run_process()", True)  
            
            if self.FixedCheckboxs['checkBox_chip_run_pll'].checkState() == self.CHECKED:
                pll_init = True 
            else:
                pll_init = False
              
            self.chip.initialize(comport = self.FixedComboboxs['comboBox_chp_port'].currentText(), 
                                mode = self.FixedComboboxs['comboBox_chip_txrx'].currentText(), 
                                beam = self.FixedComboboxs['comboBox_chip_beam'].currentText(), 
                                if_freq = self.chip_frequency['if'][self.Hz],
                                rf_freq = self.chip_frequency['rf'][self.Hz],
                                rf_band = self.FixedComboboxs["comboBox_chip_tx_band"].currentText(),
                                ref_in_MHz = self.chip_frequency['ref_clock'][self.MHz],
                                gain_array = np.ravel(self.FixedlineEdits['lineEdit_chip_pavt_gain_index'].text().split(',')).astype(int),
                                ps_array = np.ravel(self.FixedlineEdits['lineEdit_chip_pavt_phase_index'].text().split(',')).astype(int),
                                mix_gain = int(self.FixedComboboxs['comboBox_chip_mix_trx_gain'].currentText()),
                                fe_gain = int(self.FixedComboboxs['comboBox_chip_fe_trx_gain'].currentText()),
                                mix_pwr_target = self.FixedComboboxs['comboBox_chip_mix_trx_power_target'].currentText(),
                                fe_pwr_target = self.FixedComboboxs['comboBox_chip_fe_trx_power_target'].currentText(),
                                pll_init = pll_init
                                )
                
            self._chip__read_temp_th(None, sig_msg)                
            #self._chip__read_temp(sig_msg)
            #self._chip__read_vdd(sig_msg)
            
            #if self.FixedCheckboxs['checkBox_chip_run_all_on'].checkState() == self.CHECKED:            
            #    self._chip__all_on(sig_msg, "On")
                
            ret = self._sys_test_time_measure("_chip__run_process()", False) 
            self._sys_ui_unlock()
            return True         
        except Exception as e:           
            self._sys_ui_unlock()
            print(self.getTracebackStr(traceback.format_exc()))
            return False    
     
