            # drawing the graph
            for key, (beam, pol, chip, elemental, port, enable) in test_item.items(): 
                if self.checkboxes[enable].checkState() == self.CHECKED:                            
                    if self._testcom_function_is_open(): 
                        if pol == 'h':
                            #temp = 'AT-MOTCTRL=1,90,0\r\n'                                    
                            temp = 'AT-MOTCTRL=1,'+str(self.textboxes["init_Positioner_Elevation_h"].text())+','+str(self.textboxes["init_Positioner_Azimuth_h"].text())+'\r\n'
