            self.ins[self.selected_if_index].set_rf(self.ins_port.IF, "OFF")  
            self.gs.disable_beambooks_tx()
    
            if not self.no_save_log:   
                if self.f_meas: 
                    self.f_meas.close()
                    self.f_meas = 0

            self.gumstick_seq_config_tx_fe_all_off(sig_msg)  
            tret = self._sys_test_time_measure("_function_Tx_PhaseSweep_03_a()", False)  
            sig_msg.emit("textboxes", "Time_Tx_PhaseSweep_03_a", str(tret)) 
