            self._function_exporter_image_save_as_png(self.default_log_path, capture_path, self.ota_tx_pdi["Tx_PhaseSweep_47_a"])
            self.ins[self.selected_if_index].set_rf(self.ins_port.IF, "OFF")  
            self.gs.disable_beambooks_tx()
        
