    def _function_Rx_EVM(self, sig_msg): 
        try:
            self._sys_test_time_measure("_function_Rx_EVM()", True)    
              
            # BB Measurement Settings
            #if self.ins[self._inst_get_current_bb()[0]].is_connect() or self.simulation: 
            #    self.selected_bb_index = self._inst_get_current_bb()[0]
            #    pass
            #else:
            #    if not self.delete_ds_log: print("%s is not connected!" % (self._inst_get_current_bb()[1]))
            #    return

            # IF Measurement Settings
            if self.ins[self._inst_get_current_if()[0]].is_connect() or self.simulation: 
                self.selected_if_index = self._inst_get_current_if()[0]
                pass
            else:
                if not self.delete_ds_log: print("%s is not connected!" % (self._inst_get_current_if()[1]))
                return
                
            # RF Measurement Settings
            if self.ins[self._inst_get_current_rf()[0]].is_connect() or self.simulation:  
                self.selected_rf_index = self._inst_get_current_rf()[0]
                pass
            else:
                if not self.delete_ds_log: print("%s is not connected!" % (self._inst_get_current_rf()[1]))
                return

            # Gumstick Settings
            if self.simulation: 
                pass
            else:   
                if not self.delete_ds_log: print("MVBX is not connected!") 

            DrawingSingleData = {'x': [], 'y': []}       
            DrawingAllData = {'x': [], 'y': []}      
            
            if self._testcom_function_is_open(): 
                temp = 'AT-MOTCTRL=1,'+str(self.textboxes["init_Positioner_Elevation_h"].text())+','+str(self.textboxes["init_Positioner_Azimuth_h"].text())+'\r\n'
                self._ser_t.write(temp.encode('utf-8'))
                time.sleep(3)
                 
            # SG Settings  
            self.ins[self.selected_rf_index].set_parameter(self.ins_mode.MODULATION, self._inst_update_parameter(self.selected_rf_index))             
            self.ins[self.selected_rf_index].set_sg(self.ins_port.RF, self.ins_mode.MODULATION)
            self.ins[self.selected_rf_index].set_modulation(self.ins_port.RF, "ON")     
            self.ins[self.selected_rf_index].set_rf(self.ins_port.RF, "ON")   
            time.sleep(1)

            # SA Settings  
            self.ins[self.selected_if_index].set_parameter(self.ins_mode.MODULATION, self._inst_update_parameter(self.selected_if_index)) 
            self.ins[self.selected_if_index].set_sa(self.ins_port.IF, self.ins_mode.MODULATION)
            self.ins[self.selected_if_index].set_modulation(self.ins_port.IF, "ON")    
                             
            # SA Settings  
            #self.ins[self.selected_bb_index].set_parameter(self.ins_mode.MODULATION, self._inst_update_parameter(self.selected_bb_index)) 
            #self.ins[self.selected_bb_index].set_sa(self.ins_port.BB, self.ins_mode.MODULATION)
                             
            self.gumstick_seq_config_rx_fe_all_off(sig_msg)   

            self.default_log_path = os.path.dirname(os.path.realpath(__file__)) + '\\Logs'            
            if not (os.path.isdir(self.default_log_path)):
                os.makedirs(os.path.join(self.default_log_path))                
            self.logtimestr = time.strftime("%Y%m%d-%H%M%S")
                
            if not self.no_save_log:   
                if(self.f_meas): 
                    self.f_meas.close()
                    self.f_meas = 0
                path = self.default_log_path + '\\' + self.logtimestr + '_' + self.textboxes["init_name"].text() + '_' + self.textboxes["init_note"].text() + '_' + 'Rx_EVM' + '.csv'
                self.f_meas = open(path, 'w+')
                self.f_meas.write('%s,%s,%s,%s,%s,%s\n' % ("BEAM", "POL", "PORT", "PIN", "POUT", "EVM"))

            test_item = {
                0:     ('b1', 'h', 'a', 'Rx_EVM__1'),  
                1:     ('b1', 'v', 'a', 'Rx_EVM__2'), 
                2:     ('b2', 'h', 'a', 'Rx_EVM__3'),  
                3:     ('b2', 'v', 'a', 'Rx_EVM__4'),  
                4:     ('b1', 'h', 'b', 'Rx_EVM__5'),   
                5:     ('b1', 'v', 'b', 'Rx_EVM__6'),  
                6:     ('b2', 'h', 'b', 'Rx_EVM__7'), 
                7:     ('b2', 'v', 'b', 'Rx_EVM__8'), 
                8:     ('b1b1', 'hv', 'a', 'Rx_EVM__9'),  
                9:     ('b2b2', 'hv', 'a', 'Rx_EVM__10'),  
                10:     ('b1b2', 'hv', 'a', 'Rx_EVM__11'),
                11:     ('b1b2', 'vh', 'a', 'Rx_EVM__12'),    
            }    
            # clear the graph
            for key, (beam, pol, port, enable) in test_item.items():        
                DrawingSingleData = {'x': [], 'y': []}         
                self.ota_rx_plot["Rx_EVM"][key].setData(DrawingSingleData['x'], DrawingSingleData['y'], pen=pg.mkPen(self.color_pen[key], wiDSh=2))  
                
            # drawing the graph
            for key, (beam, pol, port, enable) in test_item.items(): 
                if self.checkboxes[enable].checkState() == self.CHECKED:                           
                    if self._testcom_function_is_open():   
                        if pol == 'h':
                            #temp = 'AT-MOTCTRL=1,90,0\r\n'                                    
                            temp = 'AT-MOTCTRL=1,'+str(self.textboxes["init_Positioner_Elevation_h"].text())+','+str(self.textboxes["init_Positioner_Azimuth_h"].text())+'\r\n'
                            self._ser_t.write(temp.encode('utf-8'))
                        elif pol == 'v':
                            #temp = 'AT-MOTCTRL=1,90,90\r\n'
                            temp = 'AT-MOTCTRL=1,'+str(self.textboxes["init_Positioner_Elevation_v"].text())+','+str(self.textboxes["init_Positioner_Azimuth_v"].text())+'\r\n'
                            self._ser_t.write(temp.encode('utf-8'))
                        else:
                            pass
                        time.sleep(2) 

                    if not self.delete_ds_log: print('-----------------'+beam+pol+'-----------------')
                    Pin_start = int(self.textboxes["Rx_EVM_Sweep_Pin_Start"].text())
                    Pin_stop = int(self.textboxes["Rx_EVM_Sweep_Pin_Stop"].text())
    
                    # single beam 
                    if beam == 'b1' or beam == 'b2':
                        self.gs.config_FE_RX(self.gs.Get(), beam+'_1'+pol)     
                        self.gs.config_FE_RX(self.gs.Get(), beam+'_2'+pol)    
                        self.gs.config_FE_RX(self.gs.Get(), beam+'_3'+pol)    
                        self.gs.config_FE_RX(self.gs.Get(), beam+'_4'+pol) 

                    # dual beam
                    else:
                        beam_1 = beam[:2]
                        beam_2 = beam[2:]
                        pol_1 = pol[:1]
                        pol_2 = pol[1:]
                        
                        self.gs.config_FE_RX(self.gs.Get(), beam_1+'_1'+pol_1)     
                        self.gs.config_FE_RX(self.gs.Get(), beam_1+'_2'+pol_1)    
                        self.gs.config_FE_RX(self.gs.Get(), beam_1+'_3'+pol_1)    
                        self.gs.config_FE_RX(self.gs.Get(), beam_1+'_4'+pol_1)  
                        
                        self.gs.config_FE_RX(self.gs.Get(), beam_2+'_1'+pol_2)     
                        self.gs.config_FE_RX(self.gs.Get(), beam_2+'_2'+pol_2)    
                        self.gs.config_FE_RX(self.gs.Get(), beam_2+'_3'+pol_2)    
                        self.gs.config_FE_RX(self.gs.Get(), beam_2+'_4'+pol_2)  

                    if self.simulation: time.sleep(0.02) 
                    else: time.sleep(float(self.textboxes["mvbx_trx_command_delay_1"].text()))
                    
                    self.ota_rx_pdi["Rx_EVM"].setXRange(Pin_start - 1, Pin_stop + 1)
                    self.ota_rx_pdi["Rx_EVM"].setXRange(Pin_start - 1, Pin_stop + 1)
                    for x in range(Pin_start, Pin_stop+1): 
                        sig_msg.emit("textboxes", "Note_Rx_EVM", str(x))
                                            
                        self.ins[self.selected_rf_index].set_output_power(self.ins_port.RF, str(x))  # Pin (dBm)
                        if self.simulation: time.sleep(0.02) 
                        else: time.sleep(float(self.textboxes["mt8000a_capture_delay_1"].text()))
                        
                        ret = self.ins[self.selected_if_index].measure_mod_start(self.ins_port.IF, int(self.textboxes["Measure_capture_cnt"].text()), float(self.textboxes["ms2850a_capture_delay_1"].text()))  
                        self.ins[self.selected_if_index].measure_mod_stop()  
                        print(ret[2], ret[4])
                        
                        if ret:
                            DrawingSingleData['x'].append(x)  
                            DrawingAllData['x'].append(x) 
                            #self.DrawingData['y'].append(uniform(10.0, 30.0)) 
                            DrawingSingleData['y'].append(float(ret[4])) 
                            DrawingAllData['y'].append(float(ret[4])) 
                        
                        if not self.no_save_log:   
                            self.f_meas.write('%s,%s,%s,%s,%s,%s\n' % (str(beam), str(pol), str(port), str(x), str(ret[2]), str(ret[4])))
                        self.ota_rx_plot["Rx_EVM"][key].setData(DrawingSingleData['x'], DrawingSingleData['y'], pen=pg.mkPen(self.color_pen[key], wiDSh=2))  
                        self.ota_rx_pdi["Rx_EVM"].setYRange(max(DrawingAllData['y']) + 1, min(DrawingAllData['y']) - 1)
                        
                    del DrawingSingleData['x'][:]
                    del DrawingSingleData['y'][:] 
                    self.gumstick_seq_config_rx_fe_all_off(sig_msg)  
                else:
                    # Null Write
                    if not self.delete_ds_log: print('-----------------'+beam+pol+'-----------------')
                    Pin_start = int(self.textboxes["Rx_EVM_Sweep_Pin_Start"].text())
                    Pin_stop = int(self.textboxes["Rx_EVM_Sweep_Pin_Stop"].text())

                    if not self.no_save_log:   
                        for x in range(Pin_start, Pin_stop+1): 
                            self.f_meas.write('%s,%s,%s,%s,%s,%s\n' % (str(beam), str(pol), str(port), str(x), '0', '0'))                              
                
            capture_path = self.logtimestr + '_' + self.textboxes["init_name"].text() + '_' + self.textboxes["init_note"].text() + '_' + 'Rx_EVM'
            self._function_exporter_image_save_as_png(self.default_log_path, capture_path, self.ota_rx_pdi["Rx_EVM"])
            self.ins[self.selected_rf_index].set_rf(self.ins_port.RF, "OFF")  
    
            if not self.no_save_log:   
                if self.f_meas: 
                    self.f_meas.close()
                    self.f_meas = 0

            self.gumstick_seq_config_rx_fe_all_off(sig_msg)  
            tret = self._sys_test_time_measure("_function_Rx_EVM()", False) 
            sig_msg.emit("textboxes", "Time_Rx_EVM", str(tret))
            return True
        except Exception as e:
            if not self.no_save_log:   
                if self.f_meas: 
                    self.f_meas.close()
                    self.f_meas = 0

            tret = self._sys_test_time_measure("_function_Rx_EVM()", False)
            sig_msg.emit("textboxes", "Time_Rx_EVM", str(tret))                
            print(self.getTracebackStr(traceback.format_exc()))
            return False
                
